quests[47874] = { id = 47874, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein klarer Kopf", description = "Habt Ihr Kaja hierhergeführt? Ich hab ihr gesagt, dass sie mir nich' folg'n soll. Es is' nich' sicher...\n\nMein Verstand is' noch wie benebelt, aber die Erinnerungen kehr'n langsam zurück. Jakra'zet... die Waffe...\n\nKommt, geh'n wir an die frische Luft... Ich werd Euch erzählen, was ich entdeckt hab.", sourceObjective = "Folgt Kriegswache Rakera.", completion = "Es war richtig von Talanji, dem General nich' zu trau'n. Wenn er die Waffe findet, wird unsre Stadt fall'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[47880] = { id = 47880, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Tribut für den Tod", description = "Wir ham alles fürs Ritual zusammen, es is' Zeit anzufang'n.\n\nDamit das klappt, muss ich die alt'n Worte sing'n. Das 'ne erschöpfende Aufgabe, also müsst Ihr für mich den Mojofetisch nehm'n un' den Ritualkreis zeichn'n un' dann die Trommeln schlag'n.\n\nWenn alles klappt, wird Bwonsamdi uns in den Tempel einlad'n.\n\nWenn nich', sin' unsere Seelen verlor'n.\n\nSpar'n wir uns also die Fehler.", sourceObjective = "Zeichnet mit Hanzabus Ritualfetisch einen Ritualkreis und schlagt die Trommel der Geister, um das Ritual abzuschließen.", completion = "War mutig von Euch herzukomm'n, doch mit Mut allein werdet Ihr Bwonsamdis Gunst nicht gewinn'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[47882] = { id = 47882, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Konservierte Magie", description = "Ich habe eine Idee. Wir werden uns dieses Konstrukt zunutze machen. Dafür müssen wir es nur etwas wachrütteln.\n\nEinst speicherten wir große Mengen Energie in den Leitungen des Konservatoriums. Ein wenig steckt auch noch in ihnen, aber es ist nicht viel.\n\nNehmt dies.\n\n<Y'mera übergibt Euch einen hell leuchtenden Kristall.>\n\nEr wird kleine Magieausstöße verursachen, mit denen Ihr die instabilen Verbindungen stabilisieren könnt. Die Ladung sollte ungefähr für acht reichen.\n\nWenn Ihr einige von ihnen stabilisiert, sollten wir Zugriff auf das gesamte Netzwerk erlangen.", sourceObjective = "Stabilisiert 8 instabile Energieleitungen.", completion = "Ja, ausgezeichnet. Die Leitungen sind wieder aktiv.\n\nLeider wirkt es, als ob wir das Konstrukt doch nicht so leicht aufwecken können.", sourceObjectiveStatus = "unverified-source-field" }
quests[47883] = { id = 47883, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die längste Wacht", description = "Es war gut, dass wir nach zwei Energiequellen gesucht haben. Selbst jetzt, wo die Leitungen wieder funktionieren, bewegt sich das Konstrukt nicht von der Stelle.\n\nVermutlich hat es schon zu lange geruht. Möglicherweise schon seit Eredath über Argus schwebte.\n\nDas muss eine lange und einsame Wacht gewesen sein.\n\n<Y'mera ist einen Moment lang stumm und betrachtet dabei das Konstrukt.>\n\nNur zu, rüttelt ein wenig daran. Zusammen mit einem letzten Magiestoß sollte das Ding wieder laufen.", sourceObjective = "Erweckt den Torwächter.", completion = "Macht Euch bereit, Fremder.", sourceObjectiveStatus = "unverified-source-field" }
quests[47889] = { id = 47889, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ruf des Sprechers", description = "Magni hat Euch aufgefordert, ihn im Krokullager zu treffen. Er hat etwas gefunden und hofft, dass wir damit die endlosen Armeen der Legion besiegen können.\n\nUm diesen Krieg zu überstehen, müssen wir jeden verfügbaren Vorteil nutzen. Ihr solltet Euch zu ihm begeben.", sourceObjective = "Trefft Magni im Krokullager.", completion = "Danke, dass Ihr Euch zu mir begeben habt, mein Freund. Es gibt da etwas, das Ihr sehen solltet.", sourceObjectiveStatus = "unverified-source-field" }
quests[47890] = { id = 47890, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Visionen der Pein", description = "Seit wir Argus erreicht haben, habe ich ein Flüstern vernommen. Es ist wie das von Azeroth, nur... es kommt nicht von ihr.\n\nIch bin davon überzeugt, dass Argus einen eigenen Titanen hat, der uns kontaktieren will!\n\nDie Zerschlagenen besitzen ein für sie heiliges Relikt. Hatuun sagt, dass sie ein Flüstern daraus vernehmen können... Ich glaube, dass es eine direkte Verbindung zu Argus bieten könnte!\n\nEs befindet sich in dieser Kammer. Schauen wir mal, ob wir etwas herausfinden können.", sourceObjective = "Aktiviert den heiligen Stein und werdet gemeinsam mit Magni Zeuge der Vision von Argus.", completion = "Ich weiß nicht, wie Sargeras es schaffen konnte, Aggramar zu erwecken, doch für uns verheißt das nichts Gutes, das könnt Ihr mir glauben.", sourceObjectiveStatus = "unverified-source-field" }
quests[47891] = { id = 47891, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlimme Neuigkeiten", description = "Uns herzuschicken, war die richtige Entscheidung von Azeroth, {name}. Wir müssen Sargeras aufhalten, egal, wie seine Pläne aussehen. Sonst wird uns kein Heim bleiben, wenn all dies vorüber ist.\n\nIhr solltet zu Turalyon zurückkehren und ihn wissen lassen, was wir gesehen haben. Ich bleibe hier und versuche noch mehr hilfreiche Informationen zu gewinnen.", sourceObjective = "Kehrt zu Turalyon auf die Vindikaar zurück.", completion = "Was hat Magni Euch gezeigt?", sourceObjectiveStatus = "unverified-source-field" }
quests[47892] = { id = 47892, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sturm auf die Zitadelle", description = "Wir haben in der Nähe der Nath'raxasfestung einen Bereich gesichert. Das ist eine der wichtigsten militärischen Befestigungen der Legion auf Argus.\n\nEin sofortiger und harter Schlag könnte unsere einzige Chance darstellen, das Blatt zu unseren Gunsten zu wenden.", sourceObjective = "Reist zum Schicksalspass.", completion = "Wenn wir nicht rasch vorgehen, werden die hier stationierten Dämonen uns problemlos überrennen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[47894] = { id = 47894, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hüpf, hüpf!" }
quests[47895] = { id = 47895, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Berts Bots", description = "Wenn ich in Gnomeregan aufräumen soll, muss ich es mit allen möglichen Ratten, Schaben und möglicherweise sogar der gefürchteten mutierten Rattenschabe aufnehmen können.\n\nDamit will ich sagen, dass ich diese Bots auf die Probe stellen muss! Eine echte, praxisnahe Erprobung im Feld.\n\nSind Eure Haustiere für meine Codeprüfung bereit?", sourceObjective = "Besiegt Bert im Haustierkampf.", completion = "Da muss ich wohl zurück ans Zeichenbrett!", sourceObjectiveStatus = "unverified-source-field" }
quests[47897] = { id = 47897, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zanchuliverräter", description = "Sie versuch'n, unsre Loa zu entehr'n, un' sag'n, sie wär'n falsche Götter.\n\nSie folg'n den alten Traditionen von Blut, Opfern un' Unterwerfung.\n\nDas verstößt gegen alles, an was wir glaub'n. Tötet alle Verräter, die Ihr find'n könnt.", sourceObjective = "Tötet 10 Zanchuliverräter.", completion = "Wie viele habt Ihr getötet? Das is'n guter Anfang.", sourceObjectiveStatus = "unverified-source-field" }
quests[47904] = { id = 47904, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bewahrt die wahre Zukunft", description = "Ich weiß, wie das aussieht, {name}, aber ich bitte Euch nicht aus reinem Selbsterhaltungstrieb um Hilfe.\n\nIch brauche Eure Hilfe, weil mein Tod so nicht vorgesehen ist. Ich werde sterben - das habe ich gesehen - aber es sollte erst viel später passieren. Außerdem geht die Manipulation der Zeitwege aus persönlichem Interesse so ziemlich gegen alles, wofür mein Drachenschwarm steht.\n\nHalten wir alle vier Angriffe der Drachenschreine auf. Das sollte das Problem lösen.", sourceObjective = "Haltet im Szenario Die Tode von Chromie die Angriffe des Obsidian-, Rubin-, Azur- und Smaragddrachenschreins in nur einem Versuch auf.", completion = "Wir haben alle vier Angriffe der Drachenschreine aufgehalten – aber die Zeitlinien verlaufen immer noch falsch. In einer anderen werde ich immer noch ermordet.\n\nUnsere Arbeit ist wohl noch nicht getan, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[47906] = { id = 47906, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Tode von Chromie", description = "Wir müssen wohl alle acht Angriffe auf mich innerhalb von 15 Minuten aufhalten. Ohne Unterbrechung!\n\nDas ist nicht viel Zeit, selbst für mich.\n\nAber nicht verzagen. Wenn das jemand schafft, dann wir. Seid Ihr bereit, {name}?", sourceObjective = "Haltet im Szenario Die Tode von Chromie alle acht Angriffe auf Chromie in nur einem Versuch auf.", completion = "Wir haben es geschafft! Die Zeitlinien sind wieder exakt auf Kurs und ich bin darin am Leben.", sourceObjectiveStatus = "unverified-source-field" }
quests[47915] = { id = 47915, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefangene retten", description = "Wir tun unser Bestes, damit die Kämpfe sich auf Zanchul beschränk'n un' sich nich' auf die andren Terrassen ausdehn'.\n\nWenn Ihr uns helfen wollt, dann befreit Kriegsdruidin Loti. Sie versuch'n da oben auf der Plattform, ihren Willen mit 'nem dunklen Ritual zu brech'n.\n\nIhre Seele is' an so'n Fetisch gebund'n. Ihr müsst den Fetisch find'n, wenn Ihr sie befrei'n wollt.", sourceObjective = "Sichert den Fetisch von Loti.", progress = "Findet... den... Fetisch.", completion = "Endlich frei! Oh, die werd'n jetz' leid'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[47918] = { id = 47918, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Dienste von Krag'wa", description = "Es gibt andere Kräfte, die meine Frösche bedrohen. Die abscheulichen Naga greifen meine Küste an und entziehen meinen Fröschen ihre Magie!\n\nSie wollen sich aus meinen Anhängern ein Festmahl bereiten und ihren Hunger nach Mana stillen. Ihr müsst sie aufhalten!\n\nEine mächtige Schattenjägerin namens Narez kämpft gerade gegen die Naga. Helft ihr und beendet dieses grässliche Fressen!", sourceObjective = "Trefft Schattenjägerin Narez in den Oberen Froschmarschen.", completion = "{name}! Krag'wa selbst hat Euch geschickt? Beim Loa, gesegnet is' dieser Tag, an dem er mich anerkennt. Ich brauch Eure Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[47919] = { id = 47919, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keine Macht dem Kannibalismus", description = "Natürlich haben die Trolle von Natha'vor Shoak gefangen genommen! Wäre ja sonst auch zu leicht gewesen.\n\nIch habe es satt, vor diesen Trollen davonzulaufen. Also werdet Ihr jetzt einschreiten und dem ein Ende setzen.\n\nDie Trolle von Natha'vor haben drei mächtige Hexendoktoren, die als Leichenhetzerinnen bezeichnet werden. Setzt ihnen ein Ende, das wird den Stamm ins Chaos stürzen.\n\nNatürlich könnte das alles ganz spektakulär schiefgehen und meinen grauenvollen Tag noch schlimmer machen.", sourceObjective = "Tötet die Leichenhetzerinnen Jal'aka, Yon'gi und Nog'shra.", completion = "Gute Arbeit. Jetzt, wo diese... Dinger aus dem Weg geräumt sind, sollte Chaos unter den Trollen von Natha'vor herrschen.", sourceObjectiveStatus = "unverified-source-field" }
quests[47920] = { id = 47920, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[47921] = { id = 47921, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[47922] = { id = 47922, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[47923] = { id = 47923, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[47924] = { id = 47924, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Profanitätsfilter", description = "Ich hasse diesen Ort! Ich will einfach nur nach Hause, aber das geht nicht, denn dieser Dummkopf Shoak ist verschwunden.\n\nHört zu, {race}t. Wenn Ihr mir helft, diesen Narren zu finden, werde ich Euch gut belohnen.\n\nIch könnte Shoak ja finden, aber NATÜRLICH blockieren diese dummen Totems meine Magie! Warum auch nicht?\n\nNehmt diese Schriftrolle und nutzt ihre Magie, um die Totems zu verbrennen. Ich werde mich umsehen, um herauszufinden, ob dieser Narr einfach nur irgendwo eingenickt ist.", sourceObjective = "Vernichtet 5 profane Totems mit KajoshsSchriftrolle des Infernos.", progress = "Habt Ihr schon die Totems vernichtet?", completion = "Sieht so aus, als hätte dieser Einfaltspinsel sich von den Bluttrollen fangen lassen.\n\nDas wird schnell zu Gewalt führen.", sourceObjectiveStatus = "unverified-source-field" }
quests[47925] = { id = 47925, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shoak auf der Speisekarte", description = "Ich weiß nicht, was für Unfug Shoak getrieben hat, dass er von den Trollen von Natha'vor gefangen genommen wurde. Das werden wir erst wissen, wenn Ihr ihn gerettet habt.\n\nIch wette, sie machen sich schon bereit, ihn zu einem köstlichen Gericht zu verarbeiten. Ihr müsst rasch vorgehen und ihn da rausholen!\n\nShoak ist einer der größten Tölpel, die ich kenne, die Trolle werden nur ungern auf ihre \"Mahlzeit\" verzichten.", sourceObjective = "Rettet Shoak vor den Trollen von Natha'vor.", completion = "Nochmals vielen Dank, ich war mir sicher, dass das mein Ende wäre!", sourceObjectiveStatus = "unverified-source-field" }
quests[47928] = { id = 47928, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Opfergaben für den Loa", description = "Es ist so weit. Ihr müsst mit dem großen Loa Eraka no Kimbul in Kontakt treten.\n\nIch kann nur erahnen, wie es wohl sein muss, sich in der Gegenwart einer so alten und mächtigen Gottheit zu befinden. Ihr habt den Ring der Gezeiten erhalten, also müsst Ihr es sein, <der/die> den Loa anruft. \n\nBitte überreicht dem Loa diese Opfergabe im Namen unseres Stammes. Und berichtet ihm bitte auch von unseren Problemen mit den Naga.\n\nEraka no Kimbul ist jetzt unsre einzige Hoffnung auf ein Überleben.", sourceObjective = "Trefft Euch mit Eraka no Kimbul.", progress = "Ihr müsst mit dem Loa Zwiesprache halten. Seid Ihr bereit?", completion = "Es ist so viele Jahre her, seitdem ich Besucher in meinem Tempel hatte, die würdig waren, den Ring der Gezeiten zu tragen.", sourceObjectiveStatus = "unverified-source-field" }
quests[47934] = { id = 47934, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
