quests[47939] = { id = 47939, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wenn der Schlüssel passt", description = "Die von Aschenwind sind unvernünftig. Ich wollte über meine Freilassung verhandeln, aber sie lehnen alle Angebote ab, die ich mache. \n\nSie wollen nur das, was auch immer diese Mine hervorbringt. Mein Volk weiß, dass man sich von diesem Zeug besser fernhält. Es ist instabil.\n\nIn der Mine werden Gefangene gezwungen, es abzubauen. Und wir in den Käfigen? Wir sind nur die Reserve. Wenn jemand in den Minen stirbt, schicken sie einfach einen anderen hinein.\n\nWenn Ihr mich freilasst, werde ich Euch dafür fürstlich entlohnen! Wir müssen nur den richtigen Schlüssel für diesen Käfig finden...", sourceObjective = "Sammelt 6 Schlüssel der Aschenwindhändler.", progress = "Wir müssen den richtigen Schlüssel für diesen Käfig finden.", completion = "Keiner dieser Schlüssel passt! Wir müssen eine andere Lösung finden...", sourceObjectiveStatus = "unverified-source-field" }
quests[47943] = { id = 47943, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krabbenfangen", description = "Wir sitzen hier fest und haben kaum Nahrung und Vorräte.\n\nDie aggressiven Sethrak kontrollieren das Land im Westen und die boshaften Naga die Gewässer im Osten. Wir sind gefangen zwischen einer kargen Wüste und einem unwirtlichen Ozean.\n\nWenn Ihr zur Lagune geht und dort die Naga tötet, könntet Ihr uns auf dem Rückweg ein paar Krabben mitbringen?\n\nIch fürchte, dass unser Stamm ohne Nahrung bald zugrunde gehen wird...", sourceObjective = "Fangt 8 Klemmklauenklacker.", completion = "Ihr kommt gerade rechtzeitig. Unsere Vorräte sind so gut wie aufgebraucht. Der Stamm der Tortaka dankt Euch, Reisender.", sourceObjectiveStatus = "unverified-source-field" }
quests[47945] = { id = 47945, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zum Markt, zum Markt", description = "Ihr verdient einen ganzen Haufen Dank, dass Ihr uns aus dieser Lage gerettet habt, <Festländer/Festländerin>. Und ich frage nur ungerne, aber wärt Ihr gewillt, uns bei einer weiteren Sache auszuhelfen?\n\nNoch bevor dieser Fluch unser Dorf traf, wurden die Würstchenlieferungen vom Schlächterhafen immer seltener. Wenn wir diese Würstchen nicht erhalten, kann ich meine Familie nicht mehr ernähren!\n\nWürdet Ihr einem ehrlichen Wursthändler aushelfen? Zum Schlächterhafen müsst Ihr nur die Straße dort hinab.", sourceObjective = "Trefft Thomas Zwirbler am Schlächterhafen.", completion = "Dem Licht sei Dank, dass Ihr gekommen seid!\n\nAllein komme ich hier nicht zurecht!", sourceObjectiveStatus = "unverified-source-field" }
quests[47946] = { id = 47946, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Speck muss weg", description = "Das wird vermutlich etwas merkwürdig klingen, {class}, aber einige meiner Arbeiter wurden in Schweine verwandelt! Glücklicherweise hatte ich Erledigungen zu verrichten und war fort, sonst hätte es mich sicher auch erwischt! Jetzt sind meine Männer angeleint und warten darauf... verarbeitet zu werden.\n\n<Thomas unterdrückt den Würgereiz.>\n\nIch komme an diesen Monstern nicht vorbei, aber Ihr seht so aus, als ob Ihr das schaffen würdet. Ich weiß nicht, ob Euch das hilft, aber ich könnte schwören, dass ich aus dem Lagerhaus wildes Gelächter gehört habe.\n\nBitte... rettet meine Männer!", sourceObjective = "Bindet Torben Hochtide, Kai Segelfurt, Torsten Morgengrau und Björn Stefansson los.", completion = "Danke, dass Ihr meine Arbeiter an einen sicheren Ort geschickt habt.\n\nHoffentlich müssen sie nicht lange als Schweine verweilen.", sourceObjectiveStatus = "unverified-source-field" }
quests[47947] = { id = 47947, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Große, böse Wölfe", description = "Wölfe mit merkwürdig glühenden Augen haben sich in dem Gebiet ausgebreitet! Ich weiß nicht, was sie sind oder wieso ihre Augen glühen, aber das kann nichts Gutes bedeuten. Sie müssen weg!\n\nBitte, {class}, tötet sie, bevor noch mehr meiner Freunde ums Leben kommen.", sourceObjective = "Tötet 10 verhexte Heuler im Schlächterhafen.", completion = "Jetzt wo die Monster fort sind, werden keine meiner Leute mehr getötet.", sourceObjectiveStatus = "unverified-source-field" }
quests[47948] = { id = 47948, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schweinskotelett", description = "Roland Metzler war einer der besten Metzger, mit denen ich je gearbeitet habe... aber er ist durchgedreht! Er verarbeitet noch immer Schweine zu Würstchen!\n\nIhr müsst ihn aufhalten!", sourceObjective = "Tötet Roland den Metzger.", completion = "Der arme Roland. Er war... gut in seiner Arbeit. Einer der feinsten Metzger in Drustvar. Es ist eine Schande, dass sein Talent für solch schreckliche Zwecke eingesetzt wurde.", sourceObjectiveStatus = "unverified-source-field" }
quests[47949] = { id = 47949, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das ist nicht mein Fetisch", description = "<Die glasigen Augen des Schweinsfetischs scheinen Euch zu folgen, als Ihr Euch nähert. Die düstere Macht, die von dem Hexenfetisch ausgeht, muss für die anhaltende Verwandlung der Arbeiter verantwortlich sein.\n\nVielleicht hat Thomas Zwirbler eine Idee, was man damit machen könnte.>", sourceObjective = "Bringt den Schweinsfetisch zu Thomas Zwirbler.\n\nBereitgestellter Gegenstand:", completion = "Es hat den Fluch nicht gebrochen, als Ihr ihn entfernt habt? Verdammt. Wir müssen etwas anderes probieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[47950] = { id = 47950, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Räucherschinken", description = "Dieses widerliche Ding muss dafür verantwortlich sein, dass meine Männer noch in Schweine verwandelt sind.\n\nHmm. Nun, es gibt nicht viel, das einem läuternden Feuer widerstehen kann! Ich meine, wir sollten es abfackeln!\n\nSchmeißt es in das Lagerfeuer!", sourceObjective = "Werft den Schweinsfetisch in das Lagerfeuer.", progress = "In die Flammen mit dem widerlichen Ding!", completion = "Ihr habt es geschafft! Der Zauber ist gebrochen und meine Männer sind wieder ganz normal!\n\nNun... größtenteils. Sie leben zumindest.\n\nJetzt kann sich alles bei uns wieder normalisieren. Wenn Ihr Elias in Fallhafen seht, sagt ihm, dass er bald seine Würstchen erhält.", sourceObjectiveStatus = "unverified-source-field" }
quests[47952] = { id = 47952, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die verschollene Flotte", description = "Der Orden der Gezeitenweisen unterhält eine recht imposante Abtei hier in Boralus. Wir sollten mit unserer Suche nach der Flotte dort beginnen.\n\nIrgendjemand von ihnen muss doch etwas wissen, oder? Die gesamte legendäre Flotte von Kul Tiras kann ja nicht so einfach verloren gehen!\n\nWir müssen die Fähre zur Abtei nehmen. Denkt daran, Euren Fährenpass mitzubringen!", sourceObjective = "Bucht eine Fähre zur Sturmsangabtei.", progress = "Ich war vorher noch nie in der Abtei.", completion = "Haltet Eure Augen offen. Ich bin mir nicht sicher, ob wir uneingeschränkt willkommen sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[47953] = { id = 47953, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tereck der Ausleser" }
quests[47954] = { id = 47954, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[47956] = { id = 47956, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[47959] = { id = 47959, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Spur der Kriegswache", description = "In Rakeras Notizbuch steht, dass sie unterwegs nach Süden is'. Das is' die einzige Spur, die wir ham. \n\nMeerah will auch dahin un' hat uns eingelad'n mitzukomm'. \n\nDiese Vulpera kenn' die Wüste besser als jeder andre Troll, den ich kenn. \n\nUnsre Überlebenschancen sin' besser, wenn wir zusamm' reis'n.", sourceObjective = "Reist mit Meerahs Wagen, um nach Kriegswache Rakera zu suchen.", completion = "Ah, Ihr wollt die Kriegswache such'n? Sie is' der einzige Grund, warum ich noch am Leb'n bin.", sourceObjectiveStatus = "unverified-source-field" }
quests[47960] = { id = 47960, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Tiragardesund", description = "Wir müssen Katherine Prachtmeer davon überzeugen, dass Kul Tiras sich der Allianz anschließen muss. Finn glaubt, dass das neue Schießpulver der Handelskompanie Aschenwind eine heiße Spur ist, der wir folgen sollten.", sourceObjective = "Bietet an, Aschenwind & Co. zu untersuchen.", completion = "Mit Eurer Hilfe können wir vielleicht das Vertrauen der Leute in die Führungskraft der Prachtmeers wieder aufleben lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[47961] = { id = 47961, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drustvar", description = "Die unerschütterlichen Beschützer des Hauses Kronsteig halten an der westlichen Grenze die Stellung, aber in letzter Zeit ist jeglicher Kontakt zu ihnen abgebrochen. Wir müssen uns ihre Hilfe sichern, um ganz Kul Tiras unter dem Banner von Prachtmeer zu vereinen.", sourceObjective = "Bietet an, Kontakt zum Haus Kronsteig aufzunehmen.", completion = "Ich war erst ein Mal in Drustvar, und zwar zum Jagen. Das ist ein raues Land mit einer dunklen Geschichte und abergläubischen Einwohnern. Geht dort nicht unbewaffnet hin.", sourceObjectiveStatus = "unverified-source-field" }
quests[47962] = { id = 47962, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Sturmsangtal", description = "Die Flotte von Kul Tiras ist auf See verschollen. Die Gezeitenweisen von Sturmsang könnten mit ihrer mystischen Meeresmagie unsere einzige Möglichkeit darstellen, die legendäre Flotte zu finden.", sourceObjective = "Bietet an, das Verschwinden der Flotte von Kul Tiras zu untersuchen.", completion = "Selbst unter normalen Umständen wären die Gezeitenweisen Unbekannten gegenüber misstrauisch. Ich werde Euch auf dieser Reise begleiten. So bekommt Ihr vielleicht endlich ein paar Antworten.", sourceObjectiveStatus = "unverified-source-field" }
quests[47963] = { id = 47963, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uralte Göttin", sourceObjective = "Rettet Pa'ku.", progress = "In was für einer Welt leben wir eigentlich, wenn die Gläubigen die Götter retten müssen?", completion = "Sie sind alle Ketzer, undankbares Pack! Ich werde sie alle auf einem FELSEN zerschmettern!\n\nGeht, kleiner {race}, und stellt sicher, dass die anderen Loa nicht in die gleiche Falle tappen wie ich.", sourceObjectiveStatus = "unverified-source-field" }
quests[47964] = { id = 47964, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shoe Shine Kit Tracking Quest" }
quests[47965] = { id = 47965, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der verfallene Tempel", description = "Der Loa könnte unsere letzte Hoffnung gegen die Naga sein, aber der Tempel ist verlassen und liegt in Trümmern.\n\nZwei meines Stammes sind vorausgegangen, um die Ruinen auszukundschaften. Vielleicht können sie Euch helfen, mit Eraka no Kimbul Kontakt aufzunehmen.\n\nWenn sich der Geist des Loas noch im Tempel befindet, müssen wir ihm unbedingt von unserer Not berichten.", sourceObjective = "Sprecht mit Teekcha.", completion = "Leider hatten wir bei der Kontaktaufnahme mit dem Loa nicht viel Erfolg. Der Tempeleingang ist verschlossen und der Rest der Ruinen ist voller Dschungelspinnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[47967] = { id = 47967, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Als Tiertreiber auf Argus", description = "Ohne ihre Klippensteiger haben meine Krieger nicht einmal gegen eine kleine Streitmacht der Legion eine Chance. Wenn Ihr ein paar einfangen und herbringen könntet, könnten meine Krieger unsere Leute besser schützen.", sourceObjective = "Bringt 3 wilde Klippensteiger zu Vorreiter Jerek.", progress = "Wir brauchen diese Talbuks!", completion = "Mit diesen neuen Reittieren haben unsere Streitmächte wieder eine Chance.", sourceObjectiveStatus = "unverified-source-field" }
quests[47968] = { id = 47968, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeichen und Omen", description = "<Die Bekanntmachung, die Bürgermeister Weiß gerade anbrachte, als der Zauber seine Wirkung entfaltete, deutet an, dass in letzter Zeit einige merkwürdige Dinge in der Stadt vor sich gehen.\n\nWahrscheinlich stehen diese Ereignisse in irgendeinem Zusammenhang mit diesem Zauber.\n\nVielleicht gibt es Aufzeichnungen von anderen Dorfbewohnern, die mehr Licht auf die Quelle dieser Magie werfen können.>", sourceObjective = "Untersucht die Schreiben der Dorfbewohner in Fallhafen.", progress = "<Im Geschäftsbuch sind alle Personen und Waren aufgelistet, die durch die Stadt Fallhafen kommen.>", completion = "<Die Schriften, die Ihr entdeckt habt, haben alle einen gemeinsamen Inhalt: es geht um eine alte Frau, die vor Kurzem in der Stadt angekommen ist.\n\nDieses Geschäftsbuch könnte weitere Informationen über ihren Aufenthaltsort enthalten.>", sourceObjectiveStatus = "unverified-source-field" }
quests[47969] = { id = 47969, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Fluch von Fallhafen" }
quests[47978] = { id = 47978, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Alte auf Abwegen", description = "<Aus dem Geschäftsbuch geht hervor, dass vor Kurzem eine alte Frau namens Helena Sanftmut in ein Haus ein wenig außerhalb der Stadt gezogen ist.\n\nDie Schriften der Dorfbewohner deuten an, dass sie irgendwie mit verschiedenen Übeln in Verbindung steht, die über das Dorf gekommen sind.\n\nEs ist möglich, dass sie weiß, wer hinter diesem Zauber steckt, wenn sie nicht selbst betroffen ist.>", sourceObjective = "Stellt Helena Sanftmut in ihrem Heim außerhalb von Fallhafen.", completion = "Ach, hallo, junger Herr.\n\nHier in Fallhafen kriegen wir nur wenige Besucher. Was bringt Euch in mein Heim?", sourceObjectiveStatus = "unverified-source-field" }
quests[47979] = { id = 47979, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hexenjagd", description = "Ein Fluch, der auf den Dorfbewohnern liegt? Meine Güte, wie schrecklich!\n\nAber um ganz ehrlich zu sein, in letzter Zeit gab es einige merkwürdige Ereignisse in Fallhafen. Ob die wohl damit zu tun haben könnten?\n\nSetzt Euch und trinkt ein wenig Tee. Ich erzähle Euch, was ich weiß.", sourceObjective = "Hört Euch Helena Sanftmuts Geschichte im Nebelverhangenen Vorgebirge an.", sourceObjectiveStatus = "unverified-source-field" }
quests[47980] = { id = 47980, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Furioses Vieh", description = "<Die Tiere im Vorgebirge stehen scheinbar unter Helenas Bann, und dieser Dorfbewohner ist ihnen wohl zum Opfer gefallen.\n\nDas erklärt die in letzter Zeit aus Fallhafen verschwundenen Personen.\n\nVielleicht wären sie eine kleinere Bedrohung für die Dorfbewohner, wenn es nicht mehr so viele wären.>", sourceObjective = "Tötet 10 bezauberte Tiere im Nebelverhangenen Vorgebirge.", sourceObjectiveStatus = "unverified-source-field" }
quests[47981] = { id = 47981, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fort mit dem Fluch", description = "<In Ihrer Eile hat Helena wohl ihr Zauberbuch zurückgelassen. Die Seiten dieses Buchs beschreiben ein Ritual, mit dem sie die Bewohner von Fallhafen gefangen hält.\n\nDas Bildnis, das den Zauber im Dorf hält, wird von den kleineren am Rande der Stadt geschützt. Wenn diese zerstört werden, kommt Ihr vielleicht an das Bildnis heran, das den Zauber auf die Dorfbewohner wirken lässt.>", sourceObjective = "Zerstört die 4 geringen Bildnisse im Nebelverhangenen Vorgebirge.", completion = "<Die magischen Energien, die das Bildnis umgaben, sind verschwunden.>", sourceObjectiveStatus = "unverified-source-field" }
quests[47982] = { id = 47982, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das letzte Bildnis", description = "<Der Schutz des Bildnisses wurde gebrochen.\n\nNun muss nur noch das Bildnis selbst zerstört werden.>", sourceObjective = "Zerstört das verfluchte Bildnis in Fallhafen.", completion = "Was... Was ist los? Wie lange stehe ich jetzt schon hier?\n\nEin Fluch?! Ihr sagt, das ganze Dorf steckte einfach fest? Ich wusste doch, dass irgendetwas an diesem alten Weib nicht stimmt...\n\nWie mir scheint, ist Fallhafen Euch einiges schuldig.", sourceObjectiveStatus = "unverified-source-field" }
quests[47986] = { id = 47986, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Narben der Vergangenheit", description = "Die Kriegspanzerungen der Armee des Lichts haben schon unzählige Schlachten auf Argus entschieden. Doch trotz ihrer Macht schaffen es nicht alle vom Schlachtfeld zurück.\n\nMeine Modifikationen an dieser Panzerung sollten uns den nötigen Vorteil verschaffen, doch fehlen mir noch einige Komponenten.\n\nIn Nath'raxas gibt es Überbleibsel von zurückliegenden Schlachten, aus denen wir Teile gewinnen können. Wenn Ihr dort die benötigten Komponenten finden könnt, wird die Legion unseren Zorn zu spüren bekommen.", sourceObjective = "Beschafft ein Anrufungsrelais, eine Verteidigerpanzerung und einen Urteilskern.", progress = "Habt Ihr die Komponenten?", completion = "Perfekt! Ich danke Euch, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[47988] = { id = 47988, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chaostheorie", description = "Trotz ihrer Macht und Truppenstärke braucht selbst die Brennende Legion für den Kampf eine gewisse Ordnung. Wenn Ihr diese Ordnung stört... dann fallen sie, wie solches Gesindel es sollte.\n\nDer Plan ist einfach: Lasst das Chaos in ihren Reihen wüten, dann wird dieser Tag der unsere sein.", sourceObjective = "Tötet 12 Fleischschnitzer von Nath'raxas, Verdammnisschützinnen von Nath'raxas oder unersättliche Seelenjäger und 1 Fluchlord der Nathrezim.", completion = "Jetzt, wo unter ihren Streitkräften Unordnung herrscht, können wir weitermachen.", sourceObjectiveStatus = "unverified-source-field" }
quests[47989] = { id = 47989, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herolde der Apokalypse", description = "Uns wurde eine seltene Gelegenheit geboten.\n\nUnsere Kundschafter haben zwei Priesterinnen der Shivarra entdeckt, die in den westlichen Teufelsbecken die Kriegsanstrengungen der Legion verstärken.\n\nDer innere Kreis der Auserwählten von Sargeras verlässt Antorus niemals. Wenn wir die Priesterinnen ausschalten, können wir vielleicht Furcht unter den Anhängern des Dunklen Titanen verbreiten.", sourceObjective = "Tötet Lady Häretika und Herrin Apostriss.", completion = "Beeindruckend. Ohne die Verstärkungen der Shivarra haben wir vielleicht doch noch eine Chance.", sourceObjectiveStatus = "unverified-source-field" }
quests[47990] = { id = 47990, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Hauch des Teuflischen", description = "Unsere Kriegspanzerung ist fast einsatzbereit! Sie benötigt nur noch einen Energieschub, um die Systeme zu revitalisieren.\n\nDie Hexenmeister in den Becken dort unten versorgen Teile von Argus mit Teufelsenergie, um aus solchen Kernen lebende Belagerungswaffen zu erschaffen. Wenn Ihr einen makellosen Teufelskern besorgen könntet, würde das reichen, um den Urteilskern der Kriegspanzerung in Gang zu setzen.", sourceObjective = "Beschafft einen makellosen Teufelskern.", progress = "Denkt daran - makellos!", completion = "Ja! Das ist einer!", sourceObjectiveStatus = "unverified-source-field" }
quests[47991] = { id = 47991, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dunkles Gewerk", description = "Die Eredar sind begabt darin, die durch diese Welt pulsierende Teufelsenergie zu manipulieren. Jene, die sie nicht zu lebenden Waffen formen, erschaffen andere Gefahren wie die Pfeiler des Kummers.\n\nDie Pfeiler machen es selbst für kleine Trupps schwer, in die Festung einzudringen. Bevor wir voranschreiten, müssen wir genug davon zerlegen, damit der Weg frei ist.", sourceObjective = "Zerlegt 3 Pfeiler des Kummers.", completion = "Kein Krieg lässt sich durch eine einzige Tat gewinnen, doch ohne den Schutz der Pfeiler wird auch die Festung schließlich zu Fall kommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[47992] = { id = 47992, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dämmerung der Gerechtigkeit", description = "Dank Eurer Bemühungen herrscht beim Feind Chaos und seine Verteidigungsanlagen sind außer Betrieb.\n\nWir müssen den Bereich am Fuße des Pfeilers einnehmen und ihren Kommandanten in die Enge treiben.\n\nIhr habt Euch die Ehre verdient, die Kriegspanzerung in die Schlacht zu tragen. Sobald der Weg frei ist, werden wir Euch folgen.", sourceObjective = "Benutzt die lichtgeschmiedete Kriegspanzerung und übernehmt die Kontrolle über den Hof des Rächers.", completion = "Gut gekämpft! Jetzt ist der Kommandant dran.", sourceObjectiveStatus = "unverified-source-field" }
quests[47993] = { id = 47993, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf hohem Thron", description = "Über diese Festung herrscht Lord Nath'raxas. Er hat sie als Dank dafür erhalten, dass er Argus vor so vielen Jahren der Legion ausgeliefert hat.\n\nLasst Euch nicht täuschen, er ist durchaus mächtig, aber seine Position macht ihn auch vermessen.\n\nNutzt seine Selbstüberschätzung aus und wendet die Feuerkraft der Kriegspanzerung gegen ihn, solange Euch die Chance bleibt. Wir werden in Kürze den Hof stürmen!", sourceObjective = "Besiegt Lord Nath'raxas.", completion = "Beim Licht...", sourceObjectiveStatus = "unverified-source-field" }
quests[47994] = { id = 47994, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schaffen einer Bindung", sourceObjective = "Da sie jetzt ausgiebig getestet wurde, werde ich meinen Konstrukteuren auftragen, die Kriegspanzerung noch einmal mit Energie zu versorgen, damit Ihr sie in der Schlacht nutzen könnt. Wenn Ihr möchtet, könnt Ihr sie nach Belieben am Matrixkern auswählen.", sourceObjectiveStatus = "unverified-source-field" }
quests[47995] = { id = 47995, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufgedeckte Operationen", description = "Meine Soldaten sind dort draußen, {name}.\n\nIhr müsst Baraat, Sorvos und Telaamon für mich finden. Sie waren dabei, diesen Bereich für Velen zu sichern, als die Legion sich auf uns stürzte.\n\nLasst sie wissen, dass ihr neuer Befehl lautet, umgehend zum Propheten zurückzukehren.\n\nDie Zeit für Raffinesse ist vorüber. Es befindet sich eine kleine Armee zwischen uns und ihnen. Tut, was notwendig ist.\n\nMöge das Licht Euch schützen.", sourceObjective = "Findet Baraat den Fernschützen, den Obersten Verteidiger Sorvos und Klingenmeister Telaamon.", completion = "Fareeyas Streitkräfte sind die besten der Armee des Lichts. Wenn sie an unserer Seite stehen, hat unsere Mission deutlich größere Erfolgschancen.", sourceObjectiveStatus = "unverified-source-field" }
quests[47996] = { id = 47996, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rachenscheusalausrottung" }
quests[47998] = { id = 47998, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kannibalen killen", description = "Shoak und ich hatten einige Begegnungen mit den Trollen von Natha'vor. Das muss der Grund sein, aus dem sie diesen Idioten fangen wollten.\n\nDie Frauen in diesem Stamm fressen doch tatsächlich ihre Männer... und jeden sonst, den sie in die Hände bekommen. Vermutlich bereiten sie Shoak gerade für den Mittagstisch vor.\n\nTut uns allen einen Gefallen und tötet ein paar dieser Kannibalen. Ihr Ableben würde die Welt schon ein wenig besser machen.", sourceObjective = "Tötet 10 Kannibalinnen von Natha'vor.", completion = "Ich konnte ihre Schreie bis hierher hören.\n\nDiese Bluttrolle sind wahre Monster, {race}. Wer frisst schon seine Verwandten?", sourceObjectiveStatus = "unverified-source-field" }
quests[48002] = { id = 48002, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Begrenzte Vorräte", description = "Hallo, {name}. Wie schön, wieder einmal <einen Alchemistenkollegen/eine Alchemistenkollegin> zu sehen.\n\nIch versorge unser Lager mit den Tränken, die im Kampf gegen die Dämonen notwendig sind, doch in letzter Zeit gehen mir die Vorräte aus. Normalerweise ziehen Späher aus und holen mir leere Phiolen, doch derzeit kommen immer weniger von ihnen zurück.\n\nIch verwende gebrauchtes Material wieder, so gut ich kann, deshalb sind diese Phiolen mir sehr wichtig. Wenn Ihr mir helfen und sie beschaffen könntet, werde ich Euch zeigen, wie ich den Kampf gegen die Dämonen unterstütze.", sourceObjective = "Geht zum Versteinerten Wald und findet 12 gebrauchte Phiolen.", progress = "Wie läuft die Suche? Habt Ihr schon meine Phiolen entdeckt?", completion = "Ihr habt welche gefunden! Die werden sicher reichen, um uns noch eine Weile zu versorgen.\n\nUnd hier, wie versprochen, ein Rezept für einen der Tränke, die ich für den Kampf gegen die Legion braue.", sourceObjectiveStatus = "unverified-source-field" }
quests[48003] = { id = 48003, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Geheiß des Lords", description = "Lord Norwinsen möchte Euch für die Rettung seines Sohnes persönlich danken. Warum kommt Ihr nicht zu seinem Anwesen? Wir bereiten ein Fest vor, und jeder ist willkommen.\n\nWir gehen voraus und erzählen ihm von allem, was geschehen ist. Wir sehen uns dort!", sourceObjective = "Trefft Euch mit Lord Adrian Norwinsen auf dem Anwesen der Norwinsens.", completion = "Ihr seid {name}? Der Held, der meinen Sohn vor den Troggs gerettet hat?\n\nHohoho! Ihr seid auf meinem Anwesen höchst willkommen! Bitte berichtet mir alles von dieser edelmütigen Rettung!", sourceObjectiveStatus = "unverified-source-field" }
quests[48004] = { id = 48004, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reiten für Anfänger", description = "Sicher wisst Ihr bereits, wie man reitet, aber Ihr wisst bestimmt nicht, wie man in Kul Tiras reitet!\n\nWir werden Euch für das Fest ein Pferd ausleihen. Nehmt eins von einem unserer Lehrmeister, Böttcher. Mit ihm haben seinerzeit viele Anfänger trainiert!\n\nSitzt auf, geht in den Ring und zeigt uns, was Ihr könnt! Ihr lernt bestimmt sehr schnell!", sourceObjective = "Sitzt auf Böttcher auf und übt Euch in der Reiterei von Kul Tiras.", completion = "Gut gemacht, {name}! Ich glaube, Ihr seid bereit für die nächste Stufe!", sourceObjectiveStatus = "unverified-source-field" }
quests[48005] = { id = 48005, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seid hier Gast", description = "<Mein lieber/Meine liebe> {name}, ich hoffe, dass Euch das Fest gefällt. Ich rufe jedes Jahr Reiter aus ganz Kul Tiras zusammen, um ein großes Fest des Reitsports zu feiern!\n\nIhr verdient das volle Programm. Bitte, seht Euch ganz in Ruhe das Anwesen an, genießt Speis und Trank und stellt Euch den Leuten selbst vor. Ich bestehe darauf!", sourceObjective = "Besichtigt das Anwesen und nehmt an den Festlichkeiten teil.", completion = "Wie gefällt Euch das Gelände? Wir sind immer noch im Aufbau, aber schon bald wird alles noch herrlicher sein!\n\nUm ehrlich zu sein, ich muss mich jedes Jahr selbst übertreffen. Das alles zu organisieren, ist ziemlich anstrengend, aber es lohnt sich absolut!", sourceObjectiveStatus = "unverified-source-field" }
quests[48008] = { id = 48008, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefährliche Fracht", description = "Als mir klar wurde, was geschieht, war es zu spät.\n\nDie Leute benahmen sich merkwürdig, aber ich dachte mir nichts dabei. Immerhin sah es so aus, als würden sie einfach ihre Arbeit machen.\n\nAls ich einen Teil der Fracht inspizierte, sprang diese Larve heraus und wollte sich auf meinem Gesicht festsetzen. Ich konnte sie töten, aber es war zu spät.\n\nDie ganze Ladung ist infiziert. Nehmt diese Fackel und zerstört sie.", sourceObjective = "Verbrennt 5 Fässer mit befallener Fracht.", completion = "Jetzt können wir nur noch versuchen, die Gefahr einzudämmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[48009] = { id = 48009, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Verrat der Wache", description = "Meine Jungs stecken da zu tief drin.\n\nSie haben sich irgendeiner dunklen Macht verschrieben, die hier ihr Unwesen treibt.\n\nZögert nicht, zu tun, was getan werden muss, und streckt sie nieder. Sie wussten, worauf sie sich einlassen, als sie sich für die falsche Seite entschieden haben.", sourceObjective = "Tötet 10 gehirngewaschene Vollstrecker.", completion = "Ihr tatet, was getan werden musste.", sourceObjectiveStatus = "unverified-source-field" }
quests[48013] = { id = 48013, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf der Fährte der Fährtenleser", description = "{name}, habe ich Euch von meinem Verfolgungstrank erzählt? Unsere Späher nutzen ihn, um Dämonen zu finden. Besonders ihre \"Scheusale\".\n\nDiese Kreaturen fressen die Astralwinde in der Umgebung und machen es schwer, unsere Vorräte des Krauts aufzufüllen.\n\nWenn Ihr ein paar von ihnen beseitigen könntet, wäre das eine große Hilfe für uns und wir müssten nicht anderenorts nach Vorräten suchen. Viele von ihnen befinden sich in den Annihilangruben.\n\nFür Eure Mühen würde ich Euch auch das Rezept für den Trank beibringen.", sourceObjective = "Tötet 14 Teufelsflammenplünderer in den Annihilangruben.", completion = "Ihr seid ein ehrenhafter Verbündeter, {name}. Ich danke Euch für Eure Hilfe.\n\nHier habt Ihr das Rezept, wie versprochen.", sourceObjectiveStatus = "unverified-source-field" }
quests[48014] = { id = 48014, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gilblingesindel", description = "Die Naga haben ihre kleinen, widerlichen und nach Schlamm stinkenden Diener in unser Lager geschickt. Die sind ziemlich lästig. \n\nWenn wir nichts unternehmen und ihre Zahl immer weiter zunimmt, könnten sie zu einer echten Bedrohung werden.\n\nIhr seht aus, als wäret Ihr ebenso robust wie behände. Könntet Ihr vielleicht ein paar von ihnen auslöschen?", sourceObjective = "Tötet 6 Gilblins am Strand der Plünderer.", completion = "Vielleicht lernen sie eines Tages, für sich selbst zu denken. Oder sie suchen sich zumindest ihre Meister besser aus.", sourceObjectiveStatus = "unverified-source-field" }
quests[48015] = { id = 48015, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schriftrollen des Gral", description = "Diese Gilblins treiben mich in den Wahnsinn! Sie sind wie ein Schwarm wütender Bienen, die überall herumschwirren.\n\nHm, vielleicht nicht wie Bienen, denn die sind ja nützlich, produzieren Honig und stehlen keine Dinge.\n\nJedenfalls haben sie unsere Schriftrollen gestohlen. Die meisten davon waren nutzlos, aber drei davon sind recht... mächtig. \n\nEs wäre höchst bedauerlich, wenn sie sie ihren Meistern, den Naga, aushändigen würden. Sorgt bitte für Ordnung und bringt uns unsere Schriftrollen zurück.", sourceObjective = "Sammelt 3 tortollanische Schriftrollen.", progress = "Ah, {race}, Eure Muttersprache hat mich schon immer fasziniert.", completion = "Diese Schriftrollen müssen sicher verwahrt werden.\n\nIch wage es kaum, daran zu denken, was die Naga mit dem geheimen Wissen angestellt hätten, wenn sie es hätten entschlüsseln können.", sourceObjectiveStatus = "unverified-source-field" }
quests[48016] = { id = 48016, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ansteigende Alchemie", description = "Ich hab schon gesehen, wie andere Alchemisten mit interessanten Schmuckstücken durch unser Lager gekommen sind. Ich glaube, sie bezeichnen sie als... \"Alchemistensteine\"?\n\nIch spüre die Macht, die sie von sich geben, doch sie wirken teufelsverderbt. Die Kräuter auf diesem Planeten eignen sich besonders gut zum Läutern von Verderbnis. Ich reinige damit den Ursargerit, der oft zwischen den Kräutern gefunden wird.\n\nIch bin überzeugt, dass wir, wenn wir einen geläuterten Sargerit mit einem dieser Steine verwenden, die darin enthaltene Macht erhöhen können.", sourceObjective = "Bringt Funen 75 Astralwinde, 5 Ursargerit und einen gebundenen infernalen Alchemistenstein.", progress = "Ich weiß, ich verlange eine ganze Menge an Materialien, doch sie sind notwendig.", completion = "Da habt Ihr es! Ich bin überzeugt, dass dies in Eurem Kampf gegen die Legion deutlich besser eingesetzt werden kann.\n\nIch werde Euch erklären, wie es funktioniert...", sourceObjectiveStatus = "unverified-source-field" }
quests[48021] = { id = 48021, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chromie", description = "{name}. Seid Ihr das?\n\nIch bin mir sicher, dass bei den Zeitlinien etwas Ungewöhnliches vor sich geht. Ich brauche Eure Hilfe!\n\nKommt zu mir in den Wyrmruhtempel der Drachenöde. Dort werde ich es Euch zeigen.", sourceObjective = "Erreicht den Freundschaftsrang Zeitspringer bei Chromie in der Drachenöde.", completion = "Trotz all der Probleme, die die Legion verursacht, ist das eine willkommene Mahnung: Auch wenn sie weiter unsere größte Sorge bleibt, sollten wir nicht vergessen, dass der Rest der Welt nicht einfach still steht.", sourceObjectiveStatus = "unverified-source-field" }
quests[48022] = { id = 48022, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[48023] = { id = 48023, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befehle erhalten", description = "Wir müss'n wissen, wer die Naga anführt und sie all die süßen Frösche schnapp'n lässt.\n\nEs gibt hier Truhen mit Schriftrollen, die sie alle lesen. Die Frauen geb'n sagen den Männern immer, dass sie sich an die Befehle erinnern sollen.\n\nHolt mir welche von den Schriftrollen, dann schauen wir mal, wer das Sagen hat.", sourceObjective = "Beschafft 5 explizite Anweisungen.", sourceObjectiveStatus = "unverified-source-field" }
quests[48025] = { id = 48025, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gras darüber wachsen lassen", description = "Wir werden etwas Zeit brauchen, um die Artefakte von diesem Ort zu bergen. Und diese Zeit werden uns die Naga nicht gewähren.\n\nAber wir haben einen Plan.\n\nWir verstecken einfach das, was sie nicht finden sollen, und kommen in zehn oder zwanzig Jahren zurück. Dann werden sie diesen Ort schon längst wieder vergessen haben.\n\nNehmt diese Illusionsschriftrolle und verbergt damit die mächtigen Artefakte.", sourceObjective = "Verbergt die Antiquitäten des Gral.", completion = "Die Naga leben zwar sehr lange, aber ihre Aufmerksamkeitsspanne hat ziemlich nachgelassen.\n\nDiese Antiquitäten werden in Sicherheit und gut erhalten bleiben, bis wir zurückkehren.", sourceObjectiveStatus = "unverified-source-field" }
quests[48026] = { id = 48026, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unter den Wellen", description = "Diese Hexen wagen es? In meinem Tempel?\n\nSiavass begibt sich in Sphären, die sie nicht begreifen kann. Sie und alle ihrer Art werden nicht mehr als leere Hüllen für die dunklen Mächte sein, die dort auf sie lauern.\n\nIch spüre, wie sich etwas unter uns und um uns herum regt. Es ist wie ein Beben in meinem innersten Kern.\n\nEs baut sich ein Druck auf, der stärker ist als der Druck an der tiefsten Stelle des Ozeans.\n\nWir müssen diese Mächte aufhalten. Sie sind hier nicht willkommen!", sourceObjective = "Tötet Beschwörerin Siavass und den flüsternden Schrecken.", completion = "Die Naga versuchen, etwas zu verbergen. Meine Stärke mag schwinden, aber man sollte einen Loa nie unterschätzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[48027] = { id = 48027, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Winde von Argus", description = "<Fasziniert, dass etwas so Reines weiterhin auf diesem Planeten gedeihen kann, pflückt Ihr die Pflanze. Ihr verspürt eine Macht, die kurz von ihr ausgeht und dann verschwindet.>\n\n<Als sie in Euren Händen zerfällt, fragt Ihr Euch, ob es an diesem vom Licht verlassenen Ort wohl jemanden gibt, der weiß, wie man mit diesem wertvollen Kraut umgeht.>", sourceObjective = "Findet auf Argus jemanden, der Euch beibringen kann, wie Ihr Astralwinden ernten könnt.\n\nBereitgestellter Gegenstand:", completion = "Wie ich sehe, habt Ihr versucht, Astralwinden zu sammeln. Ja, das erfordert eine ganz bestimmte Vorgehensweise.\n\nDie Pflanze verfügt über Macht, um sich vor allem zu schützen, was sie vernichten könnte. Wenn sie sich wirklich bedroht fühlt, zerstört sie sich selbst.\n\nWenn Ihr sie pflückt, dürft Ihr nicht an ihre Zerstörung denken, sondern an ihren Schutz. Es ist eine traurige Ironie, dass man sie am Ende doch für die Herstellung anderer Gegenstände vernichtet.\n\nDoch diese Täuschung ist notwendig, damit sie sich Euch überlässt.", sourceObjectiveStatus = "unverified-source-field" }
quests[48028] = { id = 48028, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jugendlicher Widerstand", description = "<Während Ihr mit dem Sammeln der Pflanzen beginnt, bemerkt Ihr, dass einige der jüngeren Blüten Eurem Vorgehen noch immer widerstreben. Vielleicht weiß Funen mehr darüber, wie man die heranwachsenden Pflanzen behandeln muss.>", sourceObjective = "Fragt Funen, wie man mit jüngeren Astralwinden umgeht.\n\nBereitgestellter Gegenstand:", completion = "In der Tat, die jüngeren Blüten sind besonders widerspenstig. Sie geben lieber ihr Leben, als demjenigen zu dienen, der sie pflückt.\n\nUm das Kraut in dieser Form zu nutzen, müsst Ihr es erst dazu überreden, nachzugeben, denn es erkennt die Absichten des Sammelnden nicht so einfach.", sourceObjectiveStatus = "unverified-source-field" }
quests[48029] = { id = 48029, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ihr Herz", description = "<Nachdem Ihr schon eine Weile mit Astralwinden zu tun hattet, habt Ihr etwas Interessantes an ihren Wurzeln entdeckt. Aus eng gewickelten Kokons schimmert durch kleine Risse Licht hervor.>\n\n<Vielleicht kann Funen Euch mehr über die Beschaffenheit dieser Lichter erklären.>", sourceObjective = "Befragt Funen zu den schimmernden Wurzeln der Astralwinde.\n\nBereitgestellter Gegenstand:", completion = "Wie ich sehe, haben die Winde begonnen, Euch vollkommen zu vertrauen. Sie offenbaren Euch nun ihr Herz.\n\nKonzentriert Eure Bemühungen darauf, dann werdet Ihr sie in ihrer Gesamtheit einsammeln können.", sourceObjectiveStatus = "unverified-source-field" }
quests[48030] = { id = 48030, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - Stratholme Scene Seen" }
quests[48031] = { id = 48031, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - Andorhal Scene Seen" }
quests[48032] = { id = 48032, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - Hyjal Scene Seen" }
quests[48033] = { id = 48033, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - Well of Eternity Scene Seen" }
quests[48034] = { id = 48034, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brocken eines Empyriumvorkommens", description = "<Als Ihr Eure Spitzhacke auf das Erz krachen lasst, befördert sie mit einem hallenden Laut einen kleinen Brocken auf den Boden. In dieser Geschwindigkeit hättet Ihr nach einem ganzen Tag noch nicht genug Erz aus dieser Ader.>\n\n<Vielleicht kann Euch jemand erklären, wie Ihr es korrekt abbauen könnt.>", sourceObjective = "Findet auf der Vindikaar jemanden, der Euch beibringen kann, wie Ihr Empyriumvorkommen abbauen könnt.\n\nBereitgestellter Gegenstand:", completion = "Für ein gutes Ergebnis ist bei Empyrium ein präziser Treffer erforderlich. Zielt mit Eurer Spitzhacke auf die hellste Stelle im Erz. Diese Stellen sind sehr klein, daher ist Präzision so wichtig.\n\nSo bricht das Vorkommen schneller auf und Ihr könnt das Erz leichter abbauen.", sourceObjectiveStatus = "unverified-source-field" }
quests[48035] = { id = 48035, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Frage des Winkels", description = "<Als Ihr den vom Vorkommen verbleibenden Empyriumstaub betrachtet, fragt Ihr Euch, ob es nicht eine bessere Methode gibt, bei der nicht mit jedem Schlag ein Teil des Erzes zerfällt.>\n\n<Vielleicht weiß Khamir noch mehr darüber.>", sourceObjective = "Sprecht mit Khamir und findet heraus, ob es eine bessere Methode gibt, um Empyriumvorkommen abzubauen.\n\nBereitgestellter Gegenstand:", completion = "Wie ich schon erwähnt habe, ist Präzision beim Empyriumabbau das Wichtigste. Ihr habt schon gelernt, die richtige Stelle zu treffen, jetzt müsst Ihr noch den richtigen Winkel kennen.\n\nHolt Eure Spitzhacke hervor, dann zeige ich Euch, was ich meine...", sourceObjectiveStatus = "unverified-source-field" }
quests[48036] = { id = 48036, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Perfektionierte Präzision", description = "<Obwohl Ihr gelernt habt, wie man so viel wie möglich vom Vorkommen gewinnt, bleibt dessen Kern noch immer unbrauchbar. Als Ihr ihn genauer betrachtet, erkennt Ihr kleine Risse in seiner Struktur.>\n\n<Vielleicht könnt Ihr dies umgehen, wenn Ihr Euch noch ein wenig mehr dazu von Khamir erklären lasst.>", sourceObjective = "Sprecht mit Khamir und findet heraus, ob es eine noch bessere Methode zum Abbau von Empyriumvorkommen gibt.\n\nBereitgestellter Gegenstand:", completion = "Ihr habt gelernt, wo und in welchem Winkel man treffen muss, doch wenn Ihr den Kern intakt lassen möchtet, müsst Ihr nun noch lernen, wie stark Ihr zuschlagen dürft.\n\nDie Risse im Kern entstehen, weil Ihr zu stark auf das Erz einschlagt. Inzwischen habt Ihr sicher begriffen, dass der Abbau von Empyrium keine einfache Aufgabe, sondern eine Kunst ist.\n\nKommt, übt den Schwung, bis er genau richtig ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[48037] = { id = 48037, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brocken eines Empyriumflözes", description = "<Anfangs dachtet Ihr, das Erz hätte eine spiegelnde Oberfläche, die den Sternenhimmel über Euch reflektiert. Doch nachdem Ihr einen Brocken gewonnen habt, begreift Ihr, dass das Erz selbst wie die Sterne glitzert.>\n\n<Vielleicht kann Euch auf der Vindikaar jemand mehr darüber erzählen, wie Ihr so ein Flöz effizienter abbauen könnt.>", sourceObjective = "Findet auf der Vindikaar jemanden, der Euch beibringen kann, wie Ihr Empyriumflöze abbauen könnt.\n\nBereitgestellter Gegenstand:", completion = "Nach dem Abbau ist Empyrium wirklich ein unvergesslicher Anblick. Während es bei Vorkommen auf Präzision ankommt, müssen Flöze freigelegt werden.\n\nWenn Ihr eine Weile damit verbringt, den umgebenden Stein zu beseitigen, wird Euch mehr Erz bleiben.", sourceObjectiveStatus = "unverified-source-field" }
quests[48038] = { id = 48038, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht einfach rumhacken", description = "<Obwohl Ihr gelernt habt, wie man das Erz freilegt, stecken noch immer große Brocken im umgebenden Gestein fest. Wenn Ihr diese Teile entfernt, bleibt Euch nicht das reine Empyrium, das Ihr benötigt.>\n\n<Vielleicht kann Khamir Euch beibringen, wie Ihr das Erz aus diesen Teilen des Flözes gewinnen könnt.>", sourceObjective = "Sprecht mit Khamir über eine Möglichkeit, mehr Erz aus Empyriumflözen zu gewinnen.\n\nBereitgestellter Gegenstand:", completion = "Empyriumflöze sind in der Hinsicht etwas knifflig. Das Erz kann sich sehr leicht mit dem umgebenden Gestein verbinden.\n\nIch habe bemerkt, dass man den Griff des Empyriums schwächen kann, wenn man mit dem Hackenstiel auf die Randbereiche hämmert. Wenn man danach hackt, sollte der Stein einfach abfallen.", sourceObjectiveStatus = "unverified-source-field" }
quests[48039] = { id = 48039, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bergbauerische Balance", description = "<Als Ihr die Wurzel des Flözes erreicht, bleiben Euch nur kleine Brocken. Als Ganzes hätte man die Menge noch verarbeiten können.>\n\n<Vielleicht weiß Khamir ja, wie man dies verhindern kann.>", sourceObjective = "Sprecht mit Khamir darüber, wie man noch mehr Erz aus Empyriumflözen gewinnen kann.\n\nBereitgestellter Gegenstand:", completion = "Wie auch bei den Vorkommen ist der Abbau von Empyrium ganz allgemein ein Balanceakt. Der Kern ist der zerbrechlichste Teil.\n\nWenn Ihr zu hart zuschlagt, bricht er, wenn Ihr zu sanft seid, dauert es Ewigkeiten. Dasselbe gilt auch beim Lösen des umgebenden Gesteins.\n\nHier, ich zeige Euch eine Methode, mit der man mit dem richtigen Maß an Stärke trifft.", sourceObjectiveStatus = "unverified-source-field" }
quests[48040] = { id = 48040, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Besudelte Fetzen", description = "<Als Ihr beginnt, dem Kadaver vorsichtig die Haut abzuziehen, bemerkt Ihr, dass sie schnell durch die Verwesung der Kreatur verdorben wird.>\n\n<Ihr zieht sie schnell ab, könnt dabei aber nur eine kleine Menge Leder und irgendetwas Stinkendes gewinnen. Vielleicht gibt es auf der Vindikaar jemanden, der Euch mehr über diese widerliche Haut berichten kann.>", sourceObjective = "Findet auf der Vindikaar jemanden, der Euch beibringen kann, wie Ihr infernalisches Leder abziehen könnt.\n\nBereitgestellter Gegenstand:", completion = "Für den Fall, dass Ihr es noch nicht erraten habt: Das Geheimnis des ordentlichen Häutens dieser Kreaturen ist die Geschwindigkeit. Sie entspringen verdorbener Energie, und sobald Ihr ihre Kadaver aufschneidet, tritt diese Energie aus.\n\nIch würde Euch empfehlen, das schnellere Abziehen der Haut zu üben.", sourceObjectiveStatus = "unverified-source-field" }
quests[48041] = { id = 48041, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der größere Schnitt", description = "<Obwohl Ihr schneller einzelne Teile der Haut abziehen könnt, verdirbt weiterhin eine Menge, bevor Ihr sie entfernen könnt.>\n\n<Vielleicht hat Enstraa ja noch bessere Ideen dazu, wie Ihr sie vor dem Verderben entfernen könnt.>", sourceObjective = "Sprecht mit Enstraa über eine bessere Methode, um infernalisches Leder zu gewinnen.\n\nBereitgestellter Gegenstand:", completion = "Ihr seid nun schneller, aber noch immer in Eurer alten Denkweise gefangen.\n\nAnstatt nacheinander kleine Stücke zu schneiden, solltet Ihr versuchen, mit wenigen großen Schnitten so viel Haut wie möglich zu entnehmen. Entfernt Euch danach vom Leichnam und schneidet sie dort in kleinere Stücke, die Ihr verwenden könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[48042] = { id = 48042, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Operationsreihenfolge", description = "<Die Häute sind nun ergiebiger, doch Ihr könnt nur wenige Zähne und Klauen sammeln, bevor die Verderbnis sie ergreift.>\n\n<Da Euch unklar ist, wie Ihr möglichst viele Zähne und Klauen gewinnen könnt, wächst in Euch das Verlangen auf ein letztes Gespräch mit Enstraa auf der Vindikaar.>", sourceObjective = "Sprecht mit Enstraa über eine bessere Methode, um die Tiere von Argus zu zerlegen.\n\nBereitgestellter Gegenstand:", completion = "Es geht Euch also nur darum, mehr Zähne und Klauen zu erhalten? Das sollte keine große Erklärung benötigen.\n\nDie Zähne erhalten die größte Menge Verderbnis aus dem Inneren der Kreatur. Wenn Ihr sie als Erstes entfernt, bleibt Euch noch eine Menge Zeit, um den Rest des Tiers zu zerlegen. Danach solltet Ihr die Haut abziehen. Als Letztes kommen die Klauen, denn die erreicht die Verderbnis erst ganz am Ende.", sourceObjectiveStatus = "unverified-source-field" }
quests[48043] = { id = 48043, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - Plating Cleared" }
quests[48044] = { id = 48044, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - Shields Cleared" }
quests[48053] = { id = 48053, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anker lichten", description = "{name}, ich möchte Euch um einen kleinen Gefallen bitten. Die Seeflotte im Hafen von Sturmwind hat große Mengen Teufelsschiefer angefordert, um Vorräte für ihre Schiffe zu fertigen.\n\nIch bin damit beschäftigt, das Sammeln hier zu koordinieren, und alle meine Boten sind immer noch unterwegs. Könntet Ihr daher bitte diese Lieferung übernehmen?\n\nWie ich höre, gibt es in der Graufangenklave hier in Dalaran ein Portal nach Sturmwind, also sollte es keine allzu lange Reise darstellen.", sourceObjective = "Bringt eine Kiste mit Teufelsschiefer zu Walcott Sutton im Hafen von Sturmwind.", progress = "Hat Alard Euch geschickt?", completion = "Was habt Ihr denn da?\n\nMehr Teufelsschiefer! Ausgezeichnet! Das Zeug wiegt Unmengen und ist ausgezeichnet für Anker geeignet.\n\nWie ich sehe, habt Ihr die Muskeln eines Schmiedes. Wollt Ihr nicht auch einmal versuchen, einen Anker herzustellen?", sourceObjectiveStatus = "unverified-source-field" }
quests[48054] = { id = 48054, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anker lichten", description = "{name}, ich möchte Euch um einen kleinen Gefallen bitten. Die Seeflotte im Bilgewasserhafen hat große Mengen Teufelsschiefer angefordert, um Vorräte für ihre Schiffe zu fertigen.\n\nIch bin damit beschäftigt, das Sammeln hier zu koordinieren, und alle meine Boten sind immer noch unterwegs. Könntet Ihr daher bitte diese Lieferung übernehmen?\n\nWie ich höre, gibt es in Windläufers Zuflucht hier in Dalaran ein Portal nach Orgrimmar, also sollte es keine allzu lange Reise darstellen.", sourceObjective = "Bringt die Kiste mit Teufelsschiefer zu Kruda Donnerhand im Bilgewasserhafen.", progress = "Hat Vridiel Euch geschickt?", completion = "Mehr Teufelsschiefer! Ausgezeichnet! Das Zeug wiegt Unmengen und ist ausgezeichnet für Anker geeignet.\n\nWie ich sehe, habt Ihr die Muskeln eines Schmiedes. Wollt Ihr nicht auch einmal versuchen, einen Anker herzustellen?", sourceObjectiveStatus = "unverified-source-field" }
quests[48055] = { id = 48055, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stärke des Empyriums", description = "Wie ich sehe, seid Ihr an meiner Rüstung interessiert. Sie besteht aus dem besten Material auf Argus, aus Empyrium. Ich bin auf die Herstellung von Brustplatten spezialisiert.\n\nIch kann Euch zeigen, wie man sie herstellt, doch dafür müsst Ihr Euer eigenes Material beschaffen. Unsere Erzvorräte gehen leider zur Neige und wir brauchen alles, was wir haben.\n\nAber hier sind die Pläne. Die zeigen Euch, was Ihr besorgen müsst...", sourceObjective = "Stellt eine Empyriumbrustplatte her. Ihr könnt die Materialien beschaffen, indem Ihr auf Argus Erz abbaut, mit anderen Spielern handelt oder sie im Auktionshaus kauft.", progress = "Ich hoffe, diese Pläne waren nicht zu kompliziert für Euch.", completion = "Das ist hochwertige Arbeit. Ihr habt sogar ein Problem gelöst, das ich mit dem Abstand zwischen vorderer und hinterer Platte hatte.\n\nEs stört Euch doch nicht, wenn ich die behalte oder? Das wäre ein fairer Tausch gegen den Bauplan, nicht wahr?", sourceObjectiveStatus = "unverified-source-field" }
quests[48056] = { id = 48056, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine wilde Gespielin", description = "Ich hatte darüber nachgedacht, wie man sich auf Argul, oder wie der Ort heißt, fortbewegen kann. Bin einfach mal davon ausgegangen, dass die Schwerkraft ganz anders ist als bei uns. Daher habe ich ein Gerät entwickelt, das Ihr über Eure Schuhe oder Hufe ziehen könnt, oder was auch immer Ihr dort unten habt.\n\nUnd dann sagt man mir, dass die Schwerkraft genau wie bei uns ist!\n\nAuch egal, ich kann den Prototyp trotzdem zum Laufen bringen. Würdet Ihr mir dabei kurz helfen? Vielleicht könnt Ihr sie ja an Kinder oder so verkaufen, wenn sie fertig sind.", sourceObjective = "Helft Hobart, den Prototyp von Gravitationsverringerungspantoffeln in Dalaran zu kalibrieren.", completion = "Der letzte Sprung sah in etwa so aus, wie ich mir das vorgestellt hatte, als ich von abweichender Schwerkraft ausgegangen war.\n\n<Hobart macht Notizen in seinen Plänen.>\n\nHier, nehmt. Sie werden nur ein paar Minuten funktionieren, bevor sie leer sind. Nutzt sie also weise.", sourceObjectiveStatus = "unverified-source-field" }
quests[48058] = { id = 48058, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mana-Etched Regalia" }
