quests[48064] = { id = 48064, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goroth Intro" }
quests[48065] = { id = 48065, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Extraterrestrische Erkundung", description = "{name}, wie ich höre, seid Ihr schon auf dem großen grünen Planeten hinter den Wolken gewesen. Da soll es ja von Dämonen nur so wimmeln.\n\nIch dachte mir, vielleicht könnten wir für diesen Planeten einen weiteren Wurmlochgenerator erschaffen, damit es leichter ist, dort hin- und herzuflitzen.\n\nDafür brauchen wir aber erst Aufnahmen der Landschaft. Ich würde ja gehen, aber... na, ich muss ja hierbleiben und mich um den Laden kümmern. Das kann ich ja nicht einfach diesen Heinis überlassen.\n\nHier, nehmt dieses Gerät und macht ein paar Aufnahmen für mich.", sourceObjective = "Benutzt das ionisierte geografische Aufnahmegerät an den Punkten, die auf Eurer Karte markiert sind. Kehrt danach zu Didi zurück.", completion = "Oh, ganz tolle Aufnahmen. Was für eine Landschaft die dort oben haben! Jetzt lasst mich nur die paar Daten festhalten...\n\n<Didi beginnt, auf einer Blaupause Notizen zu machen.>\n\nDas sollte genügen. Wie bei allen Generatoren müsst Ihr die Materialien verwenden, die Ihr vor Ort findet. Aber Ihr werdet auf dem Planeten schon Dinge finden, die sich eignen.", sourceObjectiveStatus = "unverified-source-field" }
quests[48066] = { id = 48066, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Fest für die Unseren", description = "Ah, die Hochbergtauren. Sie sind unsere Verbündeten, seit wir gemeinsam die Legion zu Fall gebracht haben.\n\nMöchtet Ihr hören, wie sie der Horde beigetreten sind? Das war eine Geschichte, sage ich Euch!\n\nAlles begann mit Baine Bluthuf und Mayla Hochberg. Baine hatte ein Festmal in Donnerfels ausgerufen, um die Hochbergtauren willkommen zu heißen...", sourceObjective = "Trefft Baine Bluthuf in Donnerfels in Mulgore.", completion = "Seid willkommen, {name}.\n\nMayla zählt Euch zu ihren treuesten Verbündeten. Dank Eurer Gegenwart sollte es möglich sein, sie von den Vorzügen eines Beitritts zur Horde zu überzeugen.", sourceObjectiveStatus = "unverified-source-field" }
quests[48067] = { id = 48067, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatten über Donnerfels", description = "Wir werden von dunklen Kräften bedroht. Ich kann nicht glauben, dass die Hochbergtauren dahinterstecken.\n\nDieser schreckliche Lärm da draußen klingt verstörend vertraut. Könnte es sein, dass... \n\nNein! Die Diener der Alten Götter greifen an! Wir müssen um Donnerfels kämpfen, {name}!", sourceObjective = "Tötet 4 dunkle Tentakel und 12 Schatten von Uul in Donnerfels.", progress = "Dass die Alten Götter auch nur diese schwachen Diener erschaffen können, ist besorgniserregend.", completion = "Die Alten Götter sind für ihre Hinterlist und Falschheit bekannt. Und jetzt dieser direkte Angriff...\n\nWonach auch immer sie suchen... sie wollen es unbedingt.", sourceObjectiveStatus = "unverified-source-field" }
quests[48069] = { id = 48069, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf der Biegezange", description = "{name}, Didi Biegezange sucht in Dalaran nach Euch. Ihr solltet vielleicht mal nachschauen, woran sie gerade arbeitet. Man sagt, da entstehen interessante Sachen.", sourceObjective = "Trefft Euch mit Didi Biegezange in Dalaran.", completion = "{name}, Ihr kommt genau rechtzeitig. Gerade habe ich dieses ionisierte geografische Aufnahmegerät fertiggestellt.\n\nIch erkläre Euch, wie Ihr es verwenden könnt...", sourceObjectiveStatus = "unverified-source-field" }
quests[48070] = { id = 48070, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Fest der Norwinsens", description = "An alle Empfänger dieser Einladung:\n\nWir laden Euch herzlich ein, am 15. jährlichen Reit- und Jagdfest der Norwinsens teilzunehmen!\n\nEs werden die unterschiedlichsten Leute und Persönlichkeiten aus ganz Kul Tiras zusammenkommen, um an den schönsten Wettkämpfen, nämlich Reiten und Jagen, teilzunehmen und Gleichgesinnte zu treffen.\n\nWir beginnen mit den von Anne Watteck geführten Jagdveranstaltungen in der Fuchsbauwaldung, gefolgt von den Reitveranstaltungen auf dem Anwesen der Norwinsens.\n\nWir hoffen, Euch alsbald dort begrüßen zu dürfen!", sourceObjective = "Trefft Anne Watteck am Rand der Fuchsbauwaldung.", completion = "Willkommen, Reisender! Möchtet Ihr an der Jagd teilnehmen?", sourceObjectiveStatus = "unverified-source-field" }
quests[48074] = { id = 48074, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einleuchtende Webarbeit", description = "Als ich zur Xenedar geeilt bin, ließ ich mein wertvollstes Werkzeug zurück. Meinen Lichtwebstuhl. Ohne ihn brauche ich deutlich länger, um unseren Verbündeten machterfüllte Kleidung zu weben.\n\nDoch Ihr seid viel mächtiger als ich. Vielleicht könntet Ihr mir ja einen Gefallen tun. Könnt Ihr nach meinem Webstuhl suchen und ihn herbringen, falls Ihr zufällig in den Gärten von Arinor seid?\n\nDann werde ich Euch liebend gerne mein Wissen über die Schneiderei von Lichtgewirktem vermitteln.", sourceObjective = "Geht zu den Gärten von Arinor und besorgt Khaelas Lichtwebstuhl.", progress = "Konntet Ihr meinen Webstuhl finden?", completion = "Ihr habt ja keine Ahnung, wie viel Zeit Ihr mir damit erspart habt, {name}. Ihr habt meinen tiefsten Dank.\n\nWie versprochen erhaltet Ihr meinen begehrten Entwurf.", sourceObjectiveStatus = "unverified-source-field" }
quests[48075] = { id = 48075, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein bunter Schlüssel", description = "{name}, wie ich höre, seid Ihr <ein Juwelenschleifer/eine Juwelenschleiferin>. Auch ich bin ein Meisterschleifer, doch meine Entwürfe sind sicher der Legion zum Opfer gefallen.\n\nAls ich aus meinem Haus eilte, hatte ich die Absicht zurückzukehren. Doch ich fürchte, dies ist nun nicht mehr möglich. Dabei habe ich dort meinen wertvollsten Besitz zurückgelassen: ein Buch mit Entwürfen der Juwelierskunst.\n\nAber Ihr, Ihr seid doch stark. Ihr könntet Euch sicher bis zu meinem Heim durchkämpfen und mein Buch zurückholen!\n\nFalls Ihr es tut, solltet Ihr wissen, dass die Truhe nur mit den Edelsteinen dieser Lande geöffnet werden kann. Man benötigt von jeder Sorte einen.", sourceObjective = "Reist zu Vorels Heim und öffnet seine Truhe mit den sechs Edelsteinen, die man beim Empyriumabbau gewinnen kann. Beschafft sein Buch der Juwelierskunst und bringt es zu ihm auf die Vindikaar zurück.", progress = "Die Kombination ist nicht schwer, platziert einfach die Edelsteine an den passenden Plätzen.", completion = "Mein Buch! Und es scheint auch nicht beschädigt zu sein. Dem Licht sei Dank.\n\nSeht her, {name}.\n\n\n\nDies sind die Schritte, um diese Edelsteine zu mächtigen Accessoires zu machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[48076] = { id = 48076, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der krönende Erfolg", description = "Da mein Buch fast für immer verloren gewesen wäre, wird mir bewusst, dass ich dieses Wissen nicht an einem einzigen Ort aufbewahren sollte. Ich möchte es an Euch weitergeben, {name}.\n\nGerade auf meine neuesten Entwürfe bin ich besonders stolz. Ich nenne sie Empyriumkronen. Jede nutzt eine andere Kombination aus Edelsteinen und verleiht daher unterschiedliche Mächte.\n\nLasst mich Euch zeigen, wie man sie fertigt. Danach sage ich Euch, was die verschiedenen Steinkombinationen bewirken.", sourceObjective = "Fertigt eine Empyriumkrone für Vorel. Ihr könnt die Materialien beschaffen, indem Ihr auf Argus Erz abbaut, mit anderen Spielern handelt oder sie im Auktionshaus kauft.", progress = "Vielleicht werdet Ihr ja irgendwann auf einen Lehrling stoßen, dem Ihr dieses Wissen weitergeben könnt.", completion = "Ausgezeichnete Arbeit, {name}. Und jetzt zu den verschiedenen Kombinationen...", sourceObjectiveStatus = "unverified-source-field" }
quests[48077] = { id = 48077, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Wieseljagd", description = "Eine der beliebtesten Jagdsportarten unter den Adligen von Boralus ist die Wieseljagd. Für diesen Sport braucht man Entschlossenheit, Geduld und Können. Meint Ihr, dieser Herausforderung gewachsen zu sein?\n\nWiesel sind flink, durchtrieben und schlau. Im Wald sind sie praktisch unmöglich zu fangen, also sucht man am besten ihren Bau und versucht, sie herauszuscheuchen.\n\nFindet ihre Baue und kommt mit ihren Pelzen zurück. Ihr Fell ist sehr weich und daher bei den Adligen sehr beliebt.", sourceObjective = "Sammelt 5 weiche Wieselpelze von Schleichwieseln.", progress = "Habt Ihr genügend Wieselpelze gesammelt?", completion = "Diese Pelze werden nicht nur die Adligen entzücken, sie beweisen auch Euer Können als Jäger.", sourceObjectiveStatus = "unverified-source-field" }
quests[48078] = { id = 48078, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erzwungenes Gleichgewicht", description = "Früher konnte ich aus den Tieren dieser Lande noch glorreiche Gegenstände fertigen. Doch dann kam die Legion und rottete die meisten wundervollen Arten aus.\n\nJetzt muss ich für die Rüstungen meiner Verbündeten verderbte Häute nutzen. Ich habe jedoch einen Weg entdeckt, wie man die Verderbnis beseitigen kann.\n\nWir nutzen einen Stoff aus besonderem, mit Lichtenergie erfülltem Garn. Ein von mir entwickeltes Öl kann mit dem Stoff zusammen das Leder läutern und nutzbar machen.\n\nHier, nehmt mein Öl und probiert es selbst.", sourceObjective = "Sammelt infernalisches Leder und lichtgewirktes Tuch und nutzt Enstraas Gerböl, um 12 Stücke geläutertes infernalisches Leder herzustellen.", progress = "Ich träume oft davon, wieder einmal mit unbeflecktem Leder zu arbeiten. Doch wer weiß schon, wann das sein könnte...", completion = "Ein interessantes, jedoch notwendiges Gleichgewicht. Ihr dürft das Öl behalten, davon habe ich reichlich.\n\nOh, und jetzt, wo Ihr das Leder reinigen könnt, sollte ich Euch auch zeigen, wie man es verwendet. Hier, ein paar Muster für Schulterschützer, nach denen Verbündete immer wieder fragen.", sourceObjectiveStatus = "unverified-source-field" }
quests[48079] = { id = 48079, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zum Hochberg", description = "Geistwandler Ebenhorn schwebt in höchster Gefahr. Er und Mayla sind zum Hochberg zurückgekehrt, aber ich glaube, sie brauchen immer noch unsere Hilfe.\n\nLasst uns nach Donnertotem reisen und schauen, wie wir Ebenhorn helfen können. Vielleicht werden unsere Taten die Bande zwischen unseren Völkern stärken.", sourceObjective = "Trefft Euch mit Mayla Hochberg in Donnertotem am Hochberg.", completion = "Ebenhorn hat uralte Zauberschutze erwähnt, die am Hochberg aufrechterhalten werden müssen. Diese Zauberschutze sollen eine große Finsternis zurückhalten.\n\nDas steht vielleicht im Zusammenhang mit der bösen Macht, die sich seiner bemächtigt hat.\n\nWir müssen darauf hoffen, dass uns Geistwandler Grauhimmel mehr darüber erzählen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[48080] = { id = 48080, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein gewisser Anteil an Gefahr", description = "Diese Adligen glauben also wirklich, Wiesel töten zu können, würde sie zu guten Jägern machen? Pah!\n\nOhne ein bisschen Gefahr ist es keine richtige Jagd. In diesen Wäldern gibt es Eber. Das bringt uns da draußen in den Bergen schon eher in Wallung! Warum erlegt Ihr nicht einige von ihnen und bringt mir ihre Hauer als Beweis?", sourceObjective = "Sammelt 8 raue Eberhauer.", progress = "Eber stellen immerhin den Anschein einer gewissen Herausforderung für Jäger dar.", completion = "<Harald stößt ein hartes Lachen aus.>\n\nGenau das habe ich gemeint!", sourceObjectiveStatus = "unverified-source-field" }
quests[48081] = { id = 48081, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die schwebende Ruine", description = "Wir wussten, dass die Legion ein schrecklicher Gegner sein würde, doch die jüngsten Ereignisse zeigen uns, dass wir mit den derzeitigen Kräften nicht gegen sie ankämpfen können. Dabei sind wir zu weit gekommen, um an einem solch kritischen Punkt zu versagen.\n\nIch weiß von einem Relikt, das uns retten könnte. Es ist in Eredath, meiner früheren Heimat. Wir müssen mit der Vindikaar von der Oberfläche von Argus abheben und die über uns schwebenden Ruinen erreichen.\n\nVielleicht werden wir dort die dringend nötige Rettung finden.", sourceObjective = "Reist nach Eredath.", completion = "<Velens Blick fällt auf die Ruinen, die vor ihm liegen.>\n\nMein Zuhause.", sourceObjectiveStatus = "unverified-source-field" }
quests[48082] = { id = 48082, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[48083] = { id = 48083, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[48084] = { id = 48084, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[48085] = { id = 48085, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[48087] = { id = 48087, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pferdebringdienst", description = "Eure Art gefällt mir, <mein Lieber/meine Liebe>!\n\nAlso, die restlichen Partygäste könnten jederzeit eintreffen. Würdet Ihr mir die Ehre erweisen, mein Lieblingspferd von meinem Anwesen auf dem Hügel zu holen?\n\nStellt Euch nur vor, welchen ersten Eindruck unsere Gäste von Euch bekommen, wenn Ihr auf dem edelsten Pferd in ganz Tiragarde angeritten kommt! Fabelhaft!", sourceObjective = "Holt Lord Norwinsens Lieblingspferd Rosa von seinem Anwesen auf dem Hügel.", completion = "Unglaublich, dass ich das jetzt sage, {name}, aber die Troggs überfallen das Anwesen!", sourceObjectiveStatus = "unverified-source-field" }
quests[48088] = { id = 48088, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nichts geht über eine Troggparty", description = "Troggs? Auf meiner Party?\n\nMein Großvater drängte sie vor vielen Jahren zurück in die Kluft, um dieses Anwesen zu bauen. Und jetzt greifen sie nach all den Jahren mit solcher Stärke an?\n\nDas ist genau das, was wir brauchen, um das diesjährige Fest unvergesslich zu machen!\n\nLasst uns Euren Heldenmut mit eigenen Augen sehen, {name}! Reitet mit Böttcher los und erledigt die Troggs! Schleift sie hinter Euch her, durchbohrt sie mit Eurer Harpune... Ganz, wie es Euch beliebt!", sourceObjective = "Tötet 20 Schmutzsteintroggs auf dem Anwesen der Norwinsens.", completion = "Eine großartige Schau! Ich habe es vor Spannung kaum aushalten können!", sourceObjectiveStatus = "unverified-source-field" }
quests[48089] = { id = 48089, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Klang der Berge", description = "Die Bewohner von Kul Tiras werden nicht kampflos aufgeben!\n\nNehmt dieses Horn. Wir nutzen es, um uns in den Bergen gegenseitig vor Gefahren zu warnen und in Kämpfen den Angriffsbefehl zu geben. Ruft damit unsere Verbündeten im Kampf gegen die Troggs zusammen!", sourceObjective = "Ruft mit dem Horn der Berge 8 Bewohner von Kul Tiras zusammen.", progress = "Gemeinsam sind wir stärker!", completion = "Unsere Leute verteidigen das Anwesen mit frischem Mut!", sourceObjectiveStatus = "unverified-source-field" }
quests[48090] = { id = 48090, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krag'was Auserwählte", description = "So 'n Schlamassel, {name}. Die Naga entzieh'n Krag'was Fröschen die Magie und lab'n sich dran.\n\nEs gibt drei Frösche, Champions von Krag'wa, die in diesem Moment gefoltert werd'n.\n\nNehmt diesen Trank. Der gibt den noblen Fröschen ihre Macht zurück. Sie verdien'n mehr, als von diesen fiesen Schlangen ausgesaugt zu werd'n.\n\nIch bleib hier. Die Naga ham bei mir 'n paar Glückstreffer gelandet. Mein ganzes Leben lang schon wollte ich Krag'wa seh'n und ich Tölpel lass mich von 'n paar Naga verwund'n.", sourceObjective = "Rettet Krol'dra die Weise, Wok'grug den Schlauen und Wag'shash den Tollkühnen.", completion = "Ihr habt's geschafft! Das wird Krag'wa freu'n, das is' mal sicher.", sourceObjectiveStatus = "unverified-source-field" }
quests[48091] = { id = 48091, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vagath der Verratene" }
quests[48092] = { id = 48092, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rache der Frösche", description = "'ne Priesterin, Zaldraxia, führt die Naga an. Sie hat herausgefund'n, wie man den Fröschen die Magie entzieh'n kann.\n\nZaldraxia schreckt vor nichts zurück und wird erst damit aufhör'n, wenn sie alle Frösche hier ausgesaugt hat.\n\nTut, was ich nich' geschafft hab, und tötet die Priesterin. Zeigt den Naga, dass Krag'wa kein Loa is', den man auf die leichte Schulter nehm'n kann.\n\nIch werd zu Krag'wa für Euren Erfolg bet'n.", sourceObjective = "Besiegt Priesterin Zaldraxia.", completion = "Da Zaldraxia tot is', sollt'n die Naga bald verschwind'n. Ihr habt getan, was ich nich' konnt, und habt meinen Dank.\n\nMöge Krag'wa Euch behüt'n. Hoffentlich erkennt er bald, wie ergeb'n ich ihm bin.", sourceObjectiveStatus = "unverified-source-field" }
quests[48093] = { id = 48093, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Naga? Nein danke!" }
