quests[48106] = { id = 48106, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wahres Missfallen" }
quests[48107] = { id = 48107, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Siegel des Erwachens", description = "Das Relikt ist zu mächtig. Wir können es nicht offen herumliegen lassen.\n\nWir müssen sofort zur Vindikaar zurückkehren. Der Prophet wird uns sagen, was zu tun ist.\n\nIch möchte Euch noch danken, {name}. Ohne Euch wäre dies nicht möglich gewesen. Quoram hätte dafür gesorgt, dass ich nie ans Siegel herangekommen wäre. Vielleicht kann ich Euch ja eines Tages die ganze Geschichte erzählen.", sourceObjective = "Kehrt zur Vindikaar zurück und sichert das Siegel des Erwachens.", progress = "Habt Ihr das Siegel des Erwachens gefunden?", completion = "Wir sind deutlich näher dran, der Krone des Triumvirats wieder ihre alte Pracht zu verleihen.", sourceObjectiveStatus = "unverified-source-field" }
quests[48108] = { id = 48108, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Tochter der Familie Kronsteig", description = "Ihr sucht nach Haus Kronsteig? Oh, da hättet Ihr keinen schlechteren Zeitpunkt wählen können!\n\nKurz bevor dieser... Fluch über uns kam, erhielt ich eine Nachricht über Luzilla, die Tochter von Lord Kronsteig. Man hat sie in Schnitztal ergriffen und angeklagt.\n\nSie behaupten, sie wäre eine Hexe!\n\nWenn man sie für schuldig befindet, wird man sie sicher hängen! Ihr müsst zur Galgenschäre eilen. Nach dem, was Ihr hier gesehen habt, könnt Ihr sie vielleicht von ihrer Unschuld überzeugen.", sourceObjective = "Trefft Euch mit Wachtmeister Henri Leumder an der Galgenschäre in Drustvar.", completion = "Seht Ihr nicht, dass wir hier zu tun haben, {class}?\n\nIhr habt hoffentlich einen Grund, diesen Prozess zu stören...", sourceObjectiveStatus = "unverified-source-field" }
quests[48109] = { id = 48109, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Augen des Waldes", description = "Je schneller ich Fräulein Kronsteig nach Aroms Wehr zurückgeleiten kann, desto besser. Aber ich werde ihren Wünschen folgen, wenn wir ihre Sicherheit gewährleisten können.\n\nIn diesen Landen gehen düstere Dinge vor sich, die Ihr nicht richtig versteht. Wenn wir verweilen müssen, müssen wir Vorbereitungen treffen.\n\nDie Tiere in diesen Wäldern dienen den düsteren Mächten als Augen. Tötet sie.", sourceObjective = "Tötet 4 wachsame Raben und 6 Streuner der Finsterrachen im Wächterwald.", completion = "Kein Tier in Sicht. Gut.\n\nDie Feinde dieses Landes dürfen uns hier nicht ungeschützt entdecken.", sourceObjectiveStatus = "unverified-source-field" }
quests[48110] = { id = 48110, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Falle eines Überfalls", description = "In diesen Wäldern gibt es mehr, um das man sich Sorgen machen muss, als nur wilde Tiere. Unser Feind nutzt Konstrukte aus Weidenruten und Gebeinen, die einen erwachsenen Mann zerfetzen können.\n\nGlücklicherweise sind diese Konstrukte nicht sonderlich aufmerksam.\n\nNehmt diese Fallen und verteilt sie im Wald hinter uns. Wenn unsere Gegner uns hier überfallen wollen, werden ihre Diener immerhin etwas aufgehalten.", sourceObjective = "Platziert 6 Fallen im Wächterwald.", progress = "Wir müssen vorbereitet sein. Hier kann überall ein Hinterhalt lauern.", completion = "Gut, diese Fallen sollten uns warnen, wenn irgendetwas versucht, sich aus den Wäldern heraus anzuschleichen.\n\nIhr habt uns eine gewisse Sicherheit gebracht, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[48111] = { id = 48111, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prüfungen des Aberglaubens", description = "Die Leute hier haben schon lange ihren Aberglauben, was Hexerei betrifft. Doch erst in letzter Zeit ist dieser Aberglauben zur Realität geworden.\n\nDie Traditionen bestimmen, dass jemand, der wegen Hexerei angeklagt ist, wählen darf, welche der verlangten Prüfungen durchgeführt werden.\n\nDie Dorfbewohner hier haben ganz klar seltsame Vorstellungen davon, was Hexen tun können und was nicht. Sprecht mit ihnen, dann finden wir heraus, wie wir meine Unschuld beweisen können.", sourceObjective = "Befragt 5 Bewohner von Schnitztal an der Galgenschäre.", progress = "Was konntet Ihr bei den Dorfbewohnern in Erfahrung bringen?", completion = "Nun, das sind wahrlich interessante Glaubensvorstellungen. Ich glaube, das mit dem Feuer und dem Ertränken kann man doch auslassen, oder?\n\nDann bleiben uns wohl nur noch drei Prüfungen...", sourceObjectiveStatus = "unverified-source-field" }
quests[48113] = { id = 48113, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Lösung stinkt", description = "Die erste Prüfung sollte nicht sonderlich schwer sein. Auch wenn ich es nicht oft tue, kann ich zweifelsohne weinen.\n\nAber um ehrlich zu sein, musste ich das noch nie auf Kommando tun.\n\nVielleicht könntet Ihr jedoch dabei helfen. In der Nähe gibt es ein Zwiebelfeld, das einem der örtlichen Bauern gehört. Es ist verlassen und das meiste dort ist inzwischen vertrocknet. Aber vielleicht könnt Ihr ja noch eine Zwiebel entdecken, die reif genug ist, um ein paar Tränen fließen zu lassen.", sourceObjective = "Sammelt eine saftige Zwiebel auf Hagendorns Feldern bei der Galgenschäre.", progress = "Hattet Ihr auf dem Zwiebelfeld Erfolg?", completion = "Großartig, Ihr habt eine gefunden! Ich habe mir schon Sorgen gemacht, dass auf dem Hof nicht mehr viel wächst.\n\nDie Leute von Drustvar könnten das ein oder andere von dieser robusten Zwiebel lernen.", sourceObjectiveStatus = "unverified-source-field" }
quests[48165] = { id = 48165, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Risiken und Nebenwirkungen", description = "Ich kann nicht behaupten, dass ich mich auf diese letzte Prüfung freue, doch alles ist besser, als in Brand gesteckt zu werden.\n\nEs heißt, dass Hexen nicht schlecht wird. Wir werden also beweisen, dass das bei mir durchaus vorkommen kann.\n\nDie Saurolisken in der Nähe haben ein Gift, das von unseren Heilern benutzt wird, wenn ein Kind versehentlich etwas verschluckt. Wenn man das Gift einnimmt, wird einem sofort schlecht und man entleert seinen Mageninhalt.\n\nIhr müsst mehrere Giftdrüsen beschaffen, um genug für eine angemessene Dosis zu erhalten. Sie intakt zu entnehmen, könnte aber schwer werden.", sourceObjective = "Sammelt 5 intakte Giftdrüsen von den Seichtwassersaurolisken bei der Galgenschäre.", progress = "Habt Ihr es hinter Euch gebracht?", completion = "Gut. Dieses Gift sollte den... gewünschten Effekt haben.\n\nWäh, ich kann nicht fassen, dass ich das tun werde.", sourceObjectiveStatus = "unverified-source-field" }
quests[48170] = { id = 48170, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blutsaugersammlung", description = "Ich kenne den Biss der Blutfliege nur allzu gut. In den Feldern um das Kronsteiganwesen sind sie überall herumgeschwirrt.\n\nAuch wenn es mir zuwider ist, sie in meine Nähe kommen zu lassen, bin ich gewillt, mich mit diesem Ärgernis auseinanderzusetzen, wenn es denn dabei hilft, diese Leute zu überzeugen.\n\nNehmt einen Krug und sammelt so viele Blutfliegen wie möglich. Sie sind in dieser Gegend nicht ungewöhnlich und sollten nicht schwer zu finden sein.", sourceObjective = "Findet ein leeres Glas und benutzt es, um 6 schwärmende Blutfliegen bei der Galgenschäre zu fangen.", completion = "Gut gemacht.\n\nBei so vielen Blutfliegen sollte wenigstens eine beißen.", sourceObjectiveStatus = "unverified-source-field" }
quests[48171] = { id = 48171, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Fluch von Schnitztal", description = "Wir können den Wachtmeister nur umstimmen, wenn wir in Erfahrung bringen, was in Schnitztal geschehen ist. Ich selbst weiß nur sehr wenig: Ein Dorf wurde von irgendwelchen monströsen Wesen überrannt.\n\nIch muss Euch bitten, an meiner Stelle dort hinzureisen, um herauszufinden, was dort vor sich gegangen ist. Ich bin sicher, Marschall Lesner wird den Wachtmeister davon abhalten, mir während Eurer Abwesenheit etwas anzutun.\n\nTut das für mich, dann werde ich Euch helfen, so gut ich kann.", sourceObjective = "Sprecht mit Evelyn Minder am Abgeholzten Ufer in Drustvar.", completion = "Ihr wollt also helfen, diesen Fluch zu brechen? Es ist schön, das zu hören. Wir können jede Hilfe brauchen.\n\nIch helfe Euch gerne, dem auf den Grund zu gehen. Aber zu allererst müssen wir ein paar unserer Dorfbewohner retten.\n\nWürdet Ihr mich unterstützen?", sourceObjectiveStatus = "unverified-source-field" }
quests[48175] = { id = 48175, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In der Senke verborgen" }
quests[48176] = { id = 48176, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Großer Ärger in Kleintortolla", sourceObjective = "Sprecht mit Toki in Kleintortolla.", sourceObjectiveStatus = "unverified-source-field" }
quests[48179] = { id = 48179, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waldläufer retten", description = "Wir können uns diese Monster so gerade eben vom Leib halten. Ohne die Dornsprecher wären wir schon längst tot. Ich hatte schon befürchtet, dass Rebecca es nicht geschafft haben könnte!\n\nIhr habt Rebeccas Vorräte gerade rechtzeitig gebracht. Unter den vielen Verwundeten im Feld sind Dornsprecher, Waldläufer und Begleiter. Ich muss hier die Stellung halten. Geht bitte zu den Ruinen und heilt so viele der Verwundeten, wie Ihr könnt!", sourceObjective = "Rettet 10 verletzte Dornsprecher, Waldläufer und ihre Begleiter.", completion = "Danke für Eure Hilfe, Festländer.", sourceObjectiveStatus = "unverified-source-field" }
quests[48180] = { id = 48180, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ernsthaft großes Problem", description = "He, <Festländer/Festländerin>!\n\nIch weiß, dass ich eigentlich Menhire umhauen und verirrte Waldläufer rausholen soll, aber habt Ihr dieses riesige Steinmonster gesehen? Ich glaube, das könnte ein Problem sein.\n\nIhr seht aus, als versteht Ihr etwas vom Kämpfen. Glaubt Ihr, wir beide können das Monster ausschalten?", sourceObjective = "Besiegt die uralte Schildwache.", completion = "Es sollte mich nicht überraschen, dass Arthur meine Befehle missachtet hat, aber über das Ergebnis kann ich mich kaum beschweren.\n\nDanke, dass Ihr ihn unterstützt und auf ihn aufgepasst habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[48181] = { id = 48181, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neeeein" }
quests[48182] = { id = 48182, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "So eine Steinerei!", description = "Mein Mentor hat die Aktivierung uralter Kräfte hier bemerkt. Wir sind hierhergekommen, um sie aufzuhalten, aber wir waren zu spät. Wir haben uns mit den Waldläufern zusammengetan, um uns gegenseitig zu unterstützen, konnten aber unsere Aufgaben nicht erfüllen.\n\nEs gibt hier eine Reihe uralter Menhire. Über sie werden die Drustkonstrukte mit Energie versorgt. Wenn Ihr sie zerstört, werden auch die Untoten in diesem Land wieder zur Ruhe kommen.\n\nVernichtet diese Menhire, damit sich das Leben hier wieder normalisieren kann.", sourceObjective = "Zerstört die uralten Menhire.", completion = "Danke, dass Ihr diese Menhire zerstört habt. Jetzt sollten wir mit den Drustkonstrukten und auferstandenen Toten sehr viel einfacher fertigwerden.", sourceObjectiveStatus = "unverified-source-field" }
quests[48183] = { id = 48183, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die lebenden Hügel", description = "Die Drustkonstrukte werden aus dem Land geformt, aber das Herz dieser Konstrukte besteht aus einem Runenmachtkern. \n\nWir haben versucht, möglichst viele von diesen Kernen zu sammeln und zu vernichten. Wir wissen, wie man die Magie dieser Kerne neutralisiert. So verhindern wir, dass noch mehr Monstrositäten mit den finsteren Herzen geschaffen werden, und schützen dieses Land und all seine Bewohner.\n\nBringt mir so viele Runenmachtkerne, wie Ihr könnt. Die Dornsprecher werden wissen, was mit ihnen zu tun ist.", sourceObjective = "Sammelt 6 Runenmachtkerne von erweckten Wächtern.", progress = "Wir wüssten es sehr zu schätzen, wenn Ihr uns alle Runenmachtkerne von erweckten Wächtern bringen könntet, die Ihr vielleicht findet.", completion = "Ausgezeichnet, {name}. Damit können wir das Land, die Leute und die Tiere hier schützen.", sourceObjectiveStatus = "unverified-source-field" }
quests[48184] = { id = 48184, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teile der Geschichte", description = "Das ist unsere Chance.\n\nWenn wir mehr über die Drust lernen, könnte das nicht nur dabei helfen, die von Fräulein Luzilla entdeckten Texte zu verstehen. Wir könnten auch mehr darüber in Erfahrung bringen, wie sie und ihre Konstrukte schließlich bezwungen wurden. Diese Lücken in der Geschichte zu füllen, könnte unser Schlüssel zum Sieg sein.\n\nDies war eine ihrer Siedlungen, bevor sie zum Ort ihrer endgültigen Niederlage wurde. Lasst uns in den Ruinen nach Hinweisen suchen.", sourceObjective = "Durchsucht die Ruinen nach Informationen über die Drust.", completion = "Gorak Tuls Tod hat seine Armee auseinandergetrieben! Das ist hieraus klar ersichtlich, aber jetzt frage ich mich... ist Gorak Tul wirklich gestorben?", sourceObjectiveStatus = "unverified-source-field" }
quests[48185] = { id = 48185, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatten des Grabes", description = "Ebenhorn sprach von einem weiteren Zauberschutz, der das Stammesland der Himmelshörner schützt. Er sagte, er befände sich in der Nähe des Himmelsgrabs. Dort hatte einst die \"Finsternis\" Gestalt angenommen.\n\nTrefft mich dort, {name}. Ich werde Euch zeigen, wie man in den Erinnerungen eines großen Helden des Himmelshornstamms wandeln kann.", sourceObjective = "Trefft Geistwandler Grauhimmel am Himmelsgrab.", completion = "Der nächste Zauberschutz ist ganz in der Nähe. Ich kann es spüren.", sourceObjectiveStatus = "unverified-source-field" }
quests[48190] = { id = 48190, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hulns Berg", description = "Wir haben gute Fortschritte bei der Reaktivierung der Zauberschutze gemacht, aber es gibt noch mehr zu tun.\n\nIch kann Ebenhorns verzweifelten Kampf spüren. Er wehrt sich zwar mit aller Kraft, aber er entgleitet uns. Wenn diese \"Finsternis\" in unser Reich einsickert, ist unser Freund wohl verloren.\n\nEbenhorn sprach von einem weiteren Zauberschutz irgendwo auf der Schneeblinden Hochebene. Trefft mich dort, damit ich Euch auf eine weitere Reise in die Erinnerungen der Vergangenheit geleiten kann.", sourceObjective = "Trefft Geistwandler Grauhimmel auf der Schneeblinden Hochebene.", completion = "Spürt Ihr es auch, {name}? So viel Macht... solche Tapferkeit.\n\nDas Echo des Geistes von Huln Hochberg umgibt uns.", sourceObjectiveStatus = "unverified-source-field" }
quests[48192] = { id = 48192, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teerspucker" }
quests[48195] = { id = 48195, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lästige Troglodyten", description = "Troggs sind schlichte Kreaturen. Sie verfügen nur über geringe Hirnfunktionen und verlassen sich zumeist allein auf ihren Überlebensinstinkt. Es sind ganz einfach Schädlinge, die vernichtet werden müssen.\n\nJe weniger es von ihnen gibt, desto besser.", sourceObjective = "Tötet 8 Schikanierer der Schmutzsteine und 3 Knochenwerfer der Schmutzsteine in der Nebelhauchkluft.", completion = "Weniger Troggs bedeuten weniger Angriffe auf unsere Leute.", sourceObjectiveStatus = "unverified-source-field" }
quests[48196] = { id = 48196, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Emils Spuren", description = "Mein Leben ist die Reiterei, nicht der Kampf. Vielleicht könnte ich es mit einem oder zwei Troggs aufnehmen, aber nicht mit einem ganzen Stamm.\n\nBitte geht zur Nebelhauchkluft und versucht, Emil zu finden. Lord Norwinsen würde überaus wütend werden, wenn ihm etwas zustieße, und das möchte niemand von uns miterleben müssen!", sourceObjective = "Folgt der Spur von Emil Norwinsen.", progress = "Seid... seid Ihr hier, um mich zu retten?", completion = "Ihr habt mich gerettet! Diese Troggs sind wirklich furchterregend. Sie haben mir Heißsporn weggenommen und mich in ihr Lager verschleppt!", sourceObjectiveStatus = "unverified-source-field" }
quests[48198] = { id = 48198, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Beweislast", description = "Ich glaube, wir haben alles Notwendige, um die drei Prüfungen der Dorfbewohner durchzuführen. Hoffen wir, dass es reicht, um sie zu überzeugen.\n\nIch bin mir sicher, Wachtmeister Leumder scharrt schon mit den Hufen, um endlich mit dem Prozess zu beginnen, und es wäre mir lieber, wenn Ihr die Prüfungen durchführen würdet. Ich kenne Euch nicht besonders gut, aber ich vertraue Euch mehr als dem Wachtmeister.\n\nSprecht mit ihm, wenn Ihr bereit seid, zu beginnen.\n\n...Und tut mir einen Gefallen. Macht schnell.", sourceObjective = "Führt an der Galgenschäre Prüfungen durch, um Luzilla Kronsteigs Unschuld zu beweisen.", completion = "Das... hat nicht so funktioniert, wie ich dachte.\n\nEs scheint, als läge mein Freispruch wahrhaft in Euren Händen.", sourceObjectiveStatus = "unverified-source-field" }
quests[48199] = { id = 48199, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das brennende Herz", description = "Der Verlust von Xe'ra ist tragisch und gerade Turalyon hat seine Probleme, ihn wegzustecken. Doch nicht einmal die Lichtmutter darf unser Schicksal für uns entscheiden.\n\nIch wünschte, Illidan hätte einen anderen Weg gefunden, um sich ihr zu verweigern... doch auch mir wurden von den Naaru Entscheidungen aufgezwungen.\n\nDas darf uns nicht von unserer Mission abbringen. Jetzt, wo die Überlebenden der Armee des Lichts an unserer Seite stehen, ist die Zeit für den Angriff gekommen.\n\nWir müssen in der Antorischen Ödnis eine sichere Stellung finden, von der aus wir den Brennenden Thron angreifen können. Es ist an der Zeit, Sargeras seinen Preis zu entreißen!", sourceObjective = "Benutzt die Navigationskonsole, um zur Antorischen Ödnis zu gelangen.", completion = "Solche Zerstörung und... solche Schrecken hätte ich mir niemals vorstellen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[48200] = { id = 48200, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sichern einer Stellung", description = "Alleria und ich haben diese Gegend bereits mit einigen unserer besten Soldaten erkundet. Wir haben Lager auf beiden Seiten unserer aktuellen Position, doch ich fürchte, sie werden schwere Angriffe hinter sich haben und Verstärkung benötigen.\n\nAls Erstes müssen wir ein Teleportersignal direkt unterhalb der Vindikaar einrichten. Von dort aus haben wir guten Zugang zu beiden Fronten.\n\nSprecht mit Romuul, wenn Ihr für die Reise zur Oberfläche bereit seid.", sourceObjective = "Reist in die Antorische Ödnis und platziert das lichtgeschmiedete Signal.", progress = "Wir müssen das Teleportersignal einrichten, wenn wir unsere Positionen verstärken wollen.", completion = "Sehr gut. Von hier aus können wir beide Lager schnell erreichen und verstärken.", sourceObjectiveStatus = "unverified-source-field" }
quests[48201] = { id = 48201, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verstärkung am Halt des Lichts", description = "Nach der Errichtung dieses Brückenkopfes müssen wir uns mit unseren Soldaten im Feld treffen.\n\nIm Süden haben wir ein großes Lager der Armee des Lichts. Es befindet sich in der Nähe des Ortes, wo die Legion ihre stärksten Krieger in einer Art Stasis hält.\n\nAlleria hat sich aufgemacht, den Bereich zu erkunden. Sucht sie und findet heraus, welche Informationen sie gesammelt hat.", sourceObjective = "Sprecht mit Alleria am Halt des Lichts.", completion = "Wir verfügen jetzt über eine Stellung hier.\n\nIch weiß aber nicht, wie lange wir sie gegen einen anhaltenden Angriff halten können.", sourceObjectiveStatus = "unverified-source-field" }
quests[48202] = { id = 48202, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verstärkung des Verhüllten Lagers", description = "Die von Euch errichtete Stellung hilft uns, den Kontakt mit unseren Leuten dort draußen zu halten.\n\nBei unserer letzten Mission an diesem Ort haben wir im Nordosten eine Bastion errichtet. Vorerst sollte ihre Verteidigung halten, doch das kann sich jederzeit ändern.\n\nIllidan ist vorausgeeilt, um sich die Lage anzusehen. Es wäre bestimmt gut, wenn Ihr ihm dort Unterstützung bieten würdet.", sourceObjective = "Sprecht mit Illidan im Verhüllten Lager.", completion = "So viele Dämonen. So viel Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[48203] = { id = 48203, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Brennende Thron", description = "Die Zeit ist gekommen, {name}, um unseren Angriff auf Antorus zu starten. Alles, wofür wir gekämpft haben, all die Opfer unserer Freunde und Familien, haben uns an diesen Punkt geführt.\n\nWir werden mit dem Urteil des Lichts auf die Mauern dieser verfluchten Zitadelle feuern und ihr Machtzentrum erstürmen. Wir werden der Legion ein Ende setzen.\n\nNach all Euren Taten ist es nur recht und billig, dass Euch diese Ehre zuteil wird. Aktiviert die Krone des Triumvirats und lasst uns die Mission zu Ende bringen.", sourceObjective = "Benutzt die Krone des Triumvirats über der Antorischen Ödnis, um den Weg nach Antorus zu öffnen.", completion = "Nach so vielen Jahren... so vielen Opfern... ist der Sieg endlich in Reichweite.", sourceObjectiveStatus = "unverified-source-field" }
quests[48230] = { id = 48230, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fragment der Vergangenheit", description = "<Euer Blick richtet sich auf den schwachen Schein des Kristallfragments. Bei genauerer Betrachtung entdeckt Ihr auf dessen Oberfläche den Teil eines Runenmusters.\n\nDas Fragment ähnelt den Argunitkristallen, mit denen die Armee des Lichts ihre Waffen mit Energie versorgt. Könnte dieser Kristall den Eredar gehört haben, die vor so langen Zeiten von Argus flohen?\n\nVielleicht kann Hauptmann Fareeya Euch ja mehr über den Kristall erzählen.>", sourceObjective = "Bringt das leuchtende Schlüsselfragment zu Hauptmann Fareeya.", completion = "<Fareeya untersucht das Kristallfragment.>\n\nDas ist alt... sehr alt. Ein Stück einer komplizierten Art von Schlüssel, wie sie von meinem Volk zum Schutz unserer wichtigsten und heiligsten Stätten genutzt wird.\n\nIch frage mich...", sourceObjectiveStatus = "unverified-source-field" }
quests[48231] = { id = 48231, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sitz des Triumvirats: Rüstung des Triumvirats", description = "Dieser neu geschmiedete Schlüssel gewährt Euch Zutritt zur Waffenkammer im Sitz des Triumvirats.\n\nIn dessen Inneren befindet sich die Rüstung des Triumvirats, die erschaffen wurde, bevor Sargeras unserer Welt das Verderben brachte. Wir dürfen nicht zulassen, dass die Mächte der Leere uns diese Rüstung entreißen.\n\nSobald wir sie haben, müsst ihr sie zu Archivar Ionaa bringen. Er hat unsere heiligsten Relikte in einer Höhle den Pfad hinauf gesammelt. Er würde sich sicher freuen, sie zu erhalten.", sourceObjective = "Bergt die Rüstung des Lichts und überbringt sie Archivar Ionaa.", progress = "Habt Ihr mir etwas mitgebracht, {class}?", completion = "Die Rüstung des Triumvirats! Ich hätte nie erwartet, sie je wieder zu erblicken. Sie ist ein Erinnerungsstück an unsere stolze Vergangenheit, die niemals von der bösartigen Legion überschattet werden wird.\n\nGaal berichtete mir von Eurer Hingabe, {name}. Ihr solltet diese Rüstung tragen. Möge sie in diesen düsteren Zeiten als Leuchtfeuer des Lichts dienen.", sourceObjectiveStatus = "unverified-source-field" }
quests[48237] = { id = 48237, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Besiegt Nekthara" }
quests[48261] = { id = 48261, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Energie zum Neuschmieden", description = "Ich habe den Schlüssel aus einem makellosen Argunitkristall geschmiedet. Leider werden all die verbleibenden für die Verteidigung der Armee des Lichts benötigt.\n\nHmm... Vielleicht würden Dendritenformationen eine Alternative bieten. Sie wurden bei der Oberschicht von Eredath oft zum Betreiben kleinerer Geräte verwendet. Wenn in den Ruinen der Stadt noch genug Gebäude intakt sind, findet man sicher noch einige bei den gefallenen Magi und Zerschlagenen.\n\nNatürlich werden wir eine Menge dieser Formationen brauchen, um den Schlüssel neu zu schmieden. Es gibt viel zu tun für Euch.", sourceObjective = "Beschafft einen Vorrat an Dendritenformationen.", progress = "Habt Ihr genug Formationen gefunden?", completion = "Oh ja. Vereinigt werden diese Formationen genug Energie bieten, damit ich die Schlüsselfragmente neu verbinden kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[48271] = { id = 48271, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Fragmente finden", description = "Das Fragment, das ihr entdeckt habt, ist nur ein Teil des Schlüssels. Ich fürchte, dass die anderen Teile von den astralen Wesen ergriffen wurden, von denen Ihr sprecht: der Schattenwache. \n\nWir müssen sie alle erlangen. Höchstwahrscheinlich befinden die Fragmente sich im Besitz der Anführer und Leutnants der Schattenwache am Sitz des Triumvirats und in dessen Umgebung.\n\nBeschafft die Schlüsselfragmente, {name}... egal, wie Ihr es anstellt.", sourceObjective = "Beschafft die fehlenden Schlüsselfragmente von den Astralen im Bereich um den Sitz des Triumvirats.", progress = "Habt Ihr alle Fragmente gefunden?", completion = "Gute Arbeit, Netherfürst. Diese Astralen hatten gegen Euch keine Chance.\n\nDa wir jetzt alle Fragmente besitzen, kann ich die Vorbereitungen zum Neuschmieden beginnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[48272] = { id = 48272, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Visionen der Furcht", description = "Ich hab es geschafft, <mein Freund/meine Liebe>. Ich habe ihn wiedergefunden!\n\nAber die Schmerzen. So viele Schmerzen. Es geht ihm nicht gut, kein bisschen!\n\nIhr müsst gemeinsam mit mir zuhören, um es zu verstehen.", sourceObjective = "Erlebt mit Magni die Vision von Argus.", progress = "Ich weiß, das ist nicht leicht zu verarbeiten, doch es könnte uns helfen, solange das überhaupt noch möglich ist.", completion = "Das Pantheon gibt es schon seit Tausenden von Jahren nicht mehr... Ich befürchte, dass dieser Plan schon vor sehr, sehr langer Zeit geschmiedet wurde.", sourceObjectiveStatus = "unverified-source-field" }
quests[48273] = { id = 48273, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Sprecher lauscht", description = "Magni hat Euch erneut zum Krokullager gerufen. Er hatte wohl einen Durchbruch bei seinen Versuchen, neuen Kontakt mit Argus aufzunehmen.\n\nIch empfehle, dass Ihr ihn umgehend aufsucht. Seine letzte Vision zeigte Aggramars Ankunft und wir wissen noch immer sehr wenig über Sargeras' Pläne.", sourceObjective = "Trefft Magni im Krokullager.", completion = "Danke, dass Ihr Euch zu mir begeben habt, mein Freund. Es gibt da etwas, das Ihr sehen solltet.", sourceObjectiveStatus = "unverified-source-field" }
quests[48277] = { id = 48277, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Sprecher sucht", description = "Unsere Streitkräfte sind für die Schlacht bereit, doch wir wissen noch immer nicht, wo Eonars Geist ist.\n\nIhr solltet Euch gleich zu Magni begeben und herausfinden, ob Ihr sie finden könnt, solange wir noch die Möglichkeit dazu haben. Wenn sie fällt, haben wir keine Chance mehr gegen Sargeras, egal, was wir aufbringen können.", sourceObjective = "Trefft Magni im Krokullager.", completion = "Ihr seid gerade rechtzeitig gekommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[48280] = { id = 48280, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Visionen eines Anderen", description = "Wer auch immer uns jetzt erreichen will, hat vielleicht die nötigen Informationen, um Eonar zu finden.\n\nWir müssen sofort herausfinden, was los ist!", sourceObjective = "Erlebt mit Magni die Vision von Argus.", completion = "Unsere Antwort liegt im Portalnetzwerk der Legion im Herzen von Antorus.", sourceObjectiveStatus = "unverified-source-field" }
quests[48282] = { id = 48282, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wichtelmutter Laglath" }
quests[48283] = { id = 48283, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Beschuldigte", description = "Ihr möchtet also mit der Beschuldigten sprechen? Warum auch nicht.\n\nDoch beeilt Euch. Ich werde nicht zulassen, dass der Prozess verzögert wird. Diese Frau wird sich für das Schicksal unseres Dorfes rechtfertigen müssen!", sourceObjective = "Sprecht mit Luzilla Kronsteig an der Galgenschäre.", completion = "Also hat Lady Kronsteig Euch gebeten, mich davon zu überzeugen, diesen Prozess seinen Gang gehen zu lassen?\n\nIch glaube, sie unterschätzt die Gefährlichkeit dieser Situation...", sourceObjectiveStatus = "unverified-source-field" }
quests[48284] = { id = 48284, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erntezeit" }
quests[48285] = { id = 48285, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lufthoheit" }
quests[48286] = { id = 48286, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kristallmethoden" }
quests[48287] = { id = 48287, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ernter der Trauer" }
quests[48288] = { id = 48288, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Antorische Oberkommando", description = "Die Legion hat über 10.000 Jahre damit verbracht, die Invasion von Azeroth zu planen. Besiegt ihre Anführer, damit sie nie wieder unsere Welt bedrohen.", sourceObjective = "Bezwingt das Antorische Oberkommando in Antorus, dem Brennenden Thron.", progress = "Habt Ihr den Feind in Antorus bereits bezwungen?", completion = "Wart Ihr in Antorus siegreich?", sourceObjectiveStatus = "unverified-source-field" }
quests[48292] = { id = 48292, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Seelenjäger", description = "Imonar ist der tödlichste Kopfgeldjäger, der je dem Wirbelnder Nether entsprungen ist. Sucht ein tiefes Loch, in das Ihr ihn stürzen könnt.", sourceObjective = "Besiegt Imonar den Seelenjäger in Antorus, dem Brennenden Thron.", progress = "Habt Ihr den Feind in Antorus bereits bezwungen?", completion = "Wart Ihr in Antorus siegreich?", sourceObjectiveStatus = "unverified-source-field" }
quests[48293] = { id = 48293, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Brennende Zirkel", description = "Nicht einmal ein Titan könnte ihre Folter ertragen. Setzt dem Zirkel der Shivarra ein Ende.", sourceObjective = "Bezwingt den Zirkel der Shivarra in Antorus, dem Brennenden Thron.", progress = "Habt Ihr den Feind in Antorus bereits bezwungen?", completion = "Wart Ihr in Antorus siegreich?", sourceObjectiveStatus = "unverified-source-field" }
quests[48294] = { id = 48294, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Zerrütter", description = "Argus ist Sargeras‘ Lösung für die Existenz. Ein Ende für alle Dinge. Setzt dem Zerrütter ein Ende, für all die, die je leben werden.", sourceObjective = "Bezwingt Argus, den Zerrütter, in Antorus, dem Brennenden Thron.", progress = "Habt Ihr den Feind in Antorus bereits bezwungen?", completion = "Wart Ihr in Antorus siegreich?", sourceObjectiveStatus = "unverified-source-field" }
quests[48295] = { id = 48295, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Antorische Oberkommando", description = "Die Legion hat über 10.000 Jahre damit verbracht, die Invasion von Azeroth zu planen. Besiegt ihre Anführer, damit sie nie wieder unsere Welt bedrohen.", sourceObjective = "Bezwingt das Antorische Oberkommando in Antorus, dem Brennenden Thron.", progress = "Habt Ihr den Feind in Antorus bereits bezwungen?", completion = "Wart Ihr in Antorus siegreich?", sourceObjectiveStatus = "unverified-source-field" }
quests[48296] = { id = 48296, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Seelenjäger", description = "Imonar ist der tödlichste Kopfgeldjäger, der je dem Wirbelnder Nether entsprungen ist. Sucht ein tiefes Loch, in das Ihr ihn stürzen könnt.", sourceObjective = "Besiegt Imonar den Seelenjäger in Antorus, dem Brennenden Thron.", progress = "Habt Ihr den Feind in Antorus bereits bezwungen?", completion = "Wart Ihr in Antorus siegreich?", sourceObjectiveStatus = "unverified-source-field" }
quests[48297] = { id = 48297, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Brennende Zirkel", description = "Nicht einmal ein Titan könnte ihre Folter ertragen. Setzt dem Zirkel der Shivarra ein Ende.", sourceObjective = "Bezwingt den Zirkel der Shivarra in Antorus, dem Brennenden Thron.", progress = "Habt Ihr den Feind in Antorus bereits bezwungen?", completion = "Wart Ihr in Antorus siegreich?", sourceObjectiveStatus = "unverified-source-field" }
