quests[48313] = { id = 48313, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Naturheilmittel", description = "Eurem Freund bleibt nicht viel Zeit. Wahrscheinlich zersetzt das Skorpidgift bereits seine Adern. \n\nOhne Heilmittel wird er bestimmt sterben.\n\nIch werde helfen. \n\nDie erste Zutat, die ich dazu brauche, ist die Wurzel eines Stachelpflaumenkaktus. Seine natürlichen heilenden Wirkstoffe eignen sich gut als Grundlage für die Salbe.", sourceObjective = "Sammelt 6 Stachelpflaumen in Zul'Ahjin.", progress = "Habt Ihr die Stachelpflaumen für die Salbe?", completion = "Mit diesen Kaktuswurzeln wird es gehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[48314] = { id = 48314, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krabbelnder Tod", description = "Skorpashigift verursacht zumeist einen langsamen, schleichenden Tod.\n\nEs ist bemerkenswert, dass Euer Freund so lange überlebt hat.\n\nWie bei den meisten Giften ist das, was Euch tötet, auch das, was Euch heilen kann. \n\nZur Herstellung eines Gegengifts muss ich das Gift mehrerer Skorpashistachel extrahieren.\n\nWenn ich das extrahierte Gift mit der Kaktuswurzelsalbe vermische, bekommen wir das Gegengift, mit dem wir seine Wunden behandeln können.", sourceObjective = "Sammelt 7 Skorpashistacheln in Zul'Ahjin.", progress = "Habt Ihr die Skorpashistacheln?", completion = "Seid vorsichtig mit den Skorpashistacheln. Unsere Lage wird nicht gerade besser, wenn einer von uns sich auch noch vergiftet. Das Skorpashigift ist sehr wirksam.", sourceObjectiveStatus = "unverified-source-field" }
quests[48315] = { id = 48315, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausgehöhlte, leere Augen", description = "<In die uralte Statue sind zwei leere Augenhöhlen eingelassen, die aussehen, als hätten sie einst Edelsteine enthalten.\n\nKönnten sich die fehlenden Edelsteine vielleicht in den Ruinen befinden?>", sourceObjective = "Findet die fehlenden Edelsteine der Statue.", progress = "<In die uralte Statue sind zwei leere Augenhöhlen eingelassen, die aussehen, als hätten sie einst Edelsteine enthalten.>", completion = "<Die Edelsteine passen perfekt in die Vertiefungen.>", sourceObjectiveStatus = "unverified-source-field" }
quests[48317] = { id = 48317, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Nase für Magie", description = "Ich habe es gefunden! Die Werte aus den Ruinen sind unmissverständlich. Irgendwo südlich und westlich des... äh... \"Fußes\", wenn man so will, befindet sich eine Quelle großer magischer Energie.\n\nDas muss das Auge von Xibala sein!\n\nWir müssen noch ein paar Sehergeräte aufstellen, um den genauen Standort des Auges herauszufinden.\n\nGeht weiter in die Ruinen hinein und trefft mich dort. Ich werde mich persönlich um diese Sache kümmern.", sourceObjective = "Trefft Euch mit Telemantenlehrling Astrandis im Westen von Xibala und helft ihm bei der Suche nach dem Auge von Xibala.", completion = "Anscheinend habe ich die, äh... Genauigkeit meiner Sehergeräte überschätzt.\n\nUnsere Feinde haben das Auge vor uns gefunden.", sourceObjectiveStatus = "unverified-source-field" }
quests[48318] = { id = 48318, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arbeitsauftrag: Lichtblutelixiere", progress = "Seid Ihr hier, um Vorräte abzuliefern?", completion = "Danke für Eure Hilfe, Alchemist. Wir haben diese Tränke wirklich dringend gebraucht." }
quests[48320] = { id = 48320, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kein Puls", sourceObjective = "Tötet 15 Raubtiere in der Pfiffblütenoase.", completion = "Für unsre Gäste gibt's noch genügend andre Viecher für die sportliche Jagd. Jetzt werd'n sie wenigstens nich' mehr schon vor ihrer Ankunft hier selbst gejagt.", sourceObjectiveStatus = "unverified-source-field" }
quests[48321] = { id = 48321, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kreative Vermarktung", description = "Die Goldhauerbande is' die beste Bande in ganz Zandalar.\n\nIch weiß das, un' Ihr wisst das. Un' alle in der Bande wiss'n das.\n\nAber wir müss'n dafür sorg'n, dass es auch alle wiss'n, die vor unserm Gasthaus steh'n.\n\nWir brauch'n was Großes... zum Beispiel 'n riesigen Hauer aus Gold!\n\nIch weiß nich', wo wir sowas find'n könn', aber ich hab 'nen Plan.\n\nIn der Oase gibt's 'n großen Saurolisken. Bringt mir 'nen riesig'n Knochen von ihm un' ich kümmer mich um den Rest.", sourceObjective = "Besorgt einen riesigen Rippenknochen von Blutkrone in der Pfiffblütenoase.", progress = "Wenn das nich' funktioniert, könn' wir uns ja in die \"Blutrippenbande\" umbenenn'.", completion = "Jawohl, damit kann ich arbeit'n!", sourceObjectiveStatus = "unverified-source-field" }
quests[48322] = { id = 48322, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Begrüßung im Goldhauer", description = "Im Goldhauer schaut's gut aus wie nie, und das is' Euch zu verdank'n!\n\nWir ham Essen, Betten un' jede Menge toter Sandwüter aufm Haufen. Davon hab ich immer geträumt!\n\n<Rhan'ka blickt in die Oase hinaus.>\n\nHört Ihr das? Da is' wohl der erste Gast von heute im Anmarsch!\n\nWollt Ihr ihn nich' begrüß'n un' ihm alles zeig'n, was Ihr hier aufgebaut habt?", sourceObjective = "Begrüßt den anreisenden Gast und präsentiert ihm den Goldhauer.", progress = "Unser erster Gast heute. Wie aufregend! Bloß nich' umbring'n!", completion = "Der Goldhauer ist die Heimat aller Verbannten. Wir halt'n hier zusamm'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[48323] = { id = 48323, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arbeitsauftrag: Tränen der Naaru", progress = "Seid Ihr hier, um Vorräte abzuliefern?", completion = "Danke für Eure Hilfe, Alchemist. Wir haben diese Tränke wirklich dringend gebraucht." }
quests[48324] = { id = 48324, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verloren in Zem'lan", description = "Den Legenden nach befindet sich ein Berg an Schätzen tief im Hafen von Zem'lan. Die Schätze wurden aus allen Ecken Azeroths geraubt. Sie werden jedoch von ewigen Monstern bewacht, die man nicht töten kann.\n\nKein Vulpera oder Verbannter hat je Schätze aus dem Hafen von Zem'lan gestohlen und ist lebend dort herausgekommen.\n\nMeiner Karawane sollte das zum ersten Mal gelingen. Unser Späher Meeki ist hineingeschlichen, um einen Weg ausfindig zu machen, aber er ist nicht zurückgekehrt.\n\nFür Euch wäre das Klügste, wenn Ihr fortgeht und nie wiederkommt. Aber, falls Ihr in den Hafen gehen solltet, findet Meeki.", sourceObjective = "Findet Meeki.", completion = "<Meekis Körper weist unzählige Stichwunden auf. Er ist eindeutig tot.>", sourceObjectiveStatus = "unverified-source-field" }
quests[48326] = { id = 48326, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das is' Meuterei", sourceObjective = "Läutet Zem'lans Gong und tötet Piratenkönig Zem'lan.", completion = "Jarrrr! Plündern un' brandschatzen!", sourceObjectiveStatus = "unverified-source-field" }
quests[48327] = { id = 48327, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine seltsame Lieferung", description = "Als unsere Karawane das letzte Mal durch die Pfiffblütenoase gezogen ist, sind wir einem merkwürdigen Zandalari begegnet, der in einer Höhle lebte. Wir haben ein paar Waren getauscht und er hat im Voraus dafür bezahlt, damit ich ihm beim nächsten Mal eine Ananas mitbringe. Keine Ahnung, warum.\n\nEs hat zwar ewig gedauert, bis ich eine auftreiben konnte, aber eine echte Vulpera hält ihre Handelsversprechen.\n\nIch wollte kurz dort haltmachen, nachdem die Sache hier erledigt ist. Aber dank Eurer Hilfe haben wir an diesem Hafen jetzt noch einen Haufen Schätze zu suchen.\n\nHättet Ihr vielleicht Zeit, die Ananas für mich auszuliefern?", sourceObjective = "Liefert die Ananas bei Rhan'ka in der Pfiffblütenoase ab.\n\nBereitgestellter Gegenstand:", completion = "<Rhan'ka untersucht die Ananas akribisch.>\n\nDiese Ananas... is'... einfach perfekt!", sourceObjectiveStatus = "unverified-source-field" }
quests[48329] = { id = 48329, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Besiegt, aber nicht gebrochen", description = "<Mit dem kristallüberzogenen Schlüssel von Bestienbrecher Hakid scheint sich der große Käfig in der Nähe öffnen zu lassen.\n\nDer Pterrordax im Käfig, der Nachkomme von Rakjan, ist stärker als die anderen Jungtiere, die Ihr am Knisternden Grat gesehen habt. Er hält den Kopf hoch erhoben und die vielen frischen Wunden und Narben, die seinen Körper übersäen, scheinen ihm nichts auszumachen.\n\nWenn Ihr ihn freilasst, wird er wahrscheinlich zu Rakjan dem Ungebrochenen auf dem Gipfel des Knisternden Grats zurückkehren wollen.>", sourceObjective = "Befreit den Nachkommen von Rakjan und bringt ihn zu Rakjan dem Ungebrochenen.", completion = "<Rakjan senkt respektvoll den Kopf.>", sourceObjectiveStatus = "unverified-source-field" }
quests[48330] = { id = 48330, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatzkammer der Zandalari", description = "Wir haben schon einige wertvolle Dinge gefunden, aber der große Preis liegt noch vor uns. Die große Kammer am Ende der Ruinen ist geradezu überfüllt mit mächtigen Artefakten.\n\nEin Schatz, wie wir ihn hier gefunden haben, kann Leben retten und in Vol'dun für ein Vermögen verkauft werden.\n\nAllerdings haben diese Gespenster, die Ihr getötet habt, nicht gelogen. Ihr Meister oder König oder was auch immer ist da drinnen sehr gut geschützt.\n\nWir müssen ihn als Gruppe erledigen. Sagt mir Bescheid, wenn Ihr bereit seid, Euch dem Kampf in der Kammer zu stellen.", sourceObjective = "Tötet Zak'rajan den Unvergänglichen in seinem Thronsaal.", completion = "Jetzt, wo Zak'rajan Geschichte ist, haben wir ein Vorrecht auf alle Schätze, die er hier drinnen gehortet hat!\n\nIhr erhaltet natürlich Euren fairen Anteil davon. Gute Arbeit wird gut bezahlt.", sourceObjectiveStatus = "unverified-source-field" }
quests[48331] = { id = 48331, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seelen entziehen", description = "<Tacha durchwühlt ihren Sack voller geplünderter Vorräte.>\n\nDie Zandalariseelen dienen den Golems also als Kraftquelle?\n\nKein Problem... Damit hatte ich schon einmal zu tun... Dafür habe ich genau das richtige Werkzeug.\n\n<Tacha zieht ein unheimliches Zandalaritotem heraus.>\n\nDas ist es! Dieses Seelenfängertotem habe ich vor Jahren in den Ruinen im Süden gefunden. Das hat uns schon einige Male aus der Klemme geholfen.\n\nSchaltet die Golems aus und legt das Totem dann neben sie, um ihnen die Seelen zu entziehen.\n\nSammelt dann das Totem wieder ein. Das brauchen wir später noch einmal.", sourceObjective = "Tötet 5 seelengefangene Wächter und nutzt das Seelenfängertotem, um den Leichen die Seelen zu entziehen.", completion = "Seht Ihr? Hab ich Euch doch gesagt, dass es mit dem Seelenfängertotem ein Kinderspiel wird. Für jedes Problem das passende Werkzeug, wie ich immer sage.", sourceObjectiveStatus = "unverified-source-field" }
quests[48332] = { id = 48332, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ranishuressourcen", description = "Hier draußen können wir es uns nicht leisten, Ressourcen zu verschwenden.\n\nMit der Zeit haben wir gelernt, alles mitzunehmen, was uns auch nur entfernt nützlich erscheint, und mit dem, was wir haben, kreativ umzugehen. Ich habe schon aus einem Totenschädel ein Boot und aus einem Sethrak einen Zelteingang gemacht.\n\nVon Magie habe ich keine Ahnung, aber ich kann Gifte und Tränke herstellen wie kein anderer.\n\nDie Magensäure eines Ranishu ergibt ein verheerendes Gift, es ist aber schwer zu bekommen. Versucht erst gar nicht, es in eine Flasche zu füllen. Ihr müsst mir ihre Mägen im Ganzen bringen, und zwar ohne Löcher!", sourceObjective = "Sammelt 25 intakte Ranishumägen.", progress = "Ihr habt ja wirklich noch alle Finger. Gut gemacht.", completion = "Ich habe noch nie jemanden gesehen, der so viele Mägen gleichzeitig getragen hat.\n\nIch bin mir nicht sicher, ob ich jetzt beeindruckt oder angeekelt sein soll.", sourceObjectiveStatus = "unverified-source-field" }
quests[48334] = { id = 48334, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die haben Golems", description = "Ich habe unzählige Ruinen in ganz Vol'dun geplündert. Von Höhlen, die von Saurolisken nur so wimmelten bis zum verfluchten Hafen von Zem'lan.\n\nIch will damit nicht angeben, sondern Euch nur vermitteln, dass ich weiß, was ich tue.\n\nIch habe deswegen so lange überlebt, weil ich mir ausreichend Zeit nehme, Risiken vermeide und nur das nehme, was ich brauche.\n\nUnd genau das werden wir hier und heute auch tun.\n\nUmi hat in ihrem ersten Späherbericht aus den Ruinen von vielen aktiven Golems gesprochen. Die Zandalarigolems sind sehr mächtig. Wir müssen herausfinden, wie sie angetrieben werden, bevor wir hineingehen können.", sourceObjective = "Findet einen fehlfunktionierenden Golem und ermittelt seine Energiequelle.", completion = "Die Golems werden von Seelen angetrieben? Hmm... \n\nWir haben es mit einem sehr mächtigen Gegner zu tun. Wir sollten spezielle Vorsichtsmaßnahmen ausarbeiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[48335] = { id = 48335, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das stärkste Tauwerk in Vol'dun", description = "Habt Ihr schon einmal versucht einen Sethrak mit Geierseilen zu fesseln? Das hält nicht lange.\n\nWenn Ihr wirklich mal etwas oder jemanden todsicher fesseln wollt, dann braucht Ihr Sandwirblerseide.\n\nDick, flexibel und nicht so klebrig, wie man denkt.\n\nKeine Angst, das wird keine Schneidereilehrstunde. Umi erwähnte in ihrem Bericht viele Sandwirbler im Innenhof der Ruine. Macht Euch auf den Weg und bringt mir ihre Seide.", sourceObjective = "Sammelt 6 Stränge Sandwirblerseide ein.", progress = "Versucht es erst gar nicht. Zerreißen ist schlicht unmöglich.", completion = "Ein Schatz muss nicht immer unbedingt aus Gold sein, {name}. Wir Vulpera haben gelernt, wertvolle Dinge in Vol'dun ausfindig zu machen, egal wo und wie.", sourceObjectiveStatus = "unverified-source-field" }
quests[48337] = { id = 48337, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arbeitsauftrag: Astralwinden", progress = "Seid Ihr hier, um Vorräte abzuliefern?", completion = "Danke für Eure Hilfe, Kräuterkundiger. Wir haben diese Astralwinden wirklich dringend gebraucht." }
quests[48338] = { id = 48338, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Benötigte Vorräte: Astralwinden", progress = "Seid Ihr hier, um Vorräte abzuliefern?", completion = "Danke für Eure Hilfe, {class}. Wir haben diese Astralwinden wirklich dringend gebraucht." }
quests[48344] = { id = 48344, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wir haben da ein Problem", description = "Wir haben da ein Problem, {name}. Die Legion ist nach Eredath gekommen.\n\nAls Ihr das Siegel nahmt, war das, als würden wir ganz Argus unsere Anwesenheit ankündigen. Antorus hat uns fest im Blick.\n\nWartet nur, es kommt noch schlimmer.\n\nVelen ist mit Hauptmann Fareeya und ihrer Streitmacht in die Gärten von Arinor gezogen, um nach dem Wappen des Wissens zu suchen. Meines Wissens sind sie jetzt alle in feindlichem Gebiet.\n\nBegleitet mich zum Konservatorium. Wir müssen Velen und die anderen zurückbringen, bevor es zu spät ist.", sourceObjective = "Trefft Turalyon am Arkankonservatorium.", completion = "Wir dürfen uns hierbei keine Fehler erlauben, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[48345] = { id = 48345, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talgaths Streitkräfte", description = "Ich muss die Suche nach dem Wappen des Wissens fortsetzen, <mein Freund/meine Freundin>. In der bevorstehenden Schlacht kann nur die Krone des Triumvirats das Blatt zu unseren Gunsten wenden.\n\nTalgaths Streitkräfte liegen zwischen uns und diesem Ziel. Ihr müsst uns einen Weg bahnen.\n\nNichts darf sich uns in den Weg stellen. Nicht einmal Talgath.", sourceObjective = "Tötet 12 Mitglieder von Talgaths Streitkräften.", completion = "<Velen scheint Eure Gegenwart nicht zu bemerken.>", sourceObjectiveStatus = "unverified-source-field" }
quests[48347] = { id = 48347, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Angelpunktwerft", description = "HILFE GESUCHT.\n\nIn der Angelpunktwerft ist eine unbekannte Krankheit ausgebrochen. Alle, die Erfahrung in der Medizin oder Heilkunde haben, sollen sich bitte umgehend bei Therold Tiefenstein melden.\n\nBürgern wird bis auf Weiteres davon abgeraten, die Angelpunktwerft aus persönlichen Gründen aufzusuchen.\n\nVielen Dank für Eure Kooperation.", sourceObjective = "Trefft Euch mit Bruder Therold an der Angelpunktwerft.", completion = "Oh! Seid Ihr aufgrund meines Aufrufes hier?\n\nDem Meer sei Dank, denn ich kann jede tüchtige Hilfe brauchen!", sourceObjectiveStatus = "unverified-source-field" }
quests[48348] = { id = 48348, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stechende Dorne", description = "Die Jäger der Sturmtakler verfügen über die größte Körperstärke in ganz Kul Tiras. Aber ohne meine Erfindungen wären sie zweifellos kaum in der Lage, so beeindruckende Beute zu erlegen!\n\nDarf ich Euch vorstellen: eine ganz gewöhnliche Harpune. Fügt man jedoch ein klein wenig gnomische Genialität hinzu, wird aus dieser durchschnittlichen Waffe etwas ganz Besonderes! \n\nAlles, was ich dazu brauche, sind Dorne von den Rochen im Hafen. Aus ihnen kann ich ein Gift herstellen, das selbst das größte aller Seemonster betäuben kann!", sourceObjective = "Sammelt 4 Giftdorne von Dornenschwanzrochen.", progress = "Seht Euch vor diesen Stacheln vor, {name}! Sie könnten selbst jemand Eures Formats ganz einfach in die Knie zwingen!", completion = "Potzblitz!\n\nDanke, Ihr seid sehr freundlich. Das sollte reichen! Ich werde mich an die Arbeit machen!", sourceObjectiveStatus = "unverified-source-field" }
quests[48349] = { id = 48349, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arbeitsauftrag: Empyrium", progress = "Seid Ihr hier, um Vorräte abzuliefern?", completion = "Danke für Eure Hilfe, Minenarbeiter. Wir haben dieses Empyrium wirklich dringend gebraucht." }
quests[48352] = { id = 48352, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Heilmittel aus dem Meer", description = "Ihr mögt es vielleicht nicht glauben, aber Seetang zählt zu den bedeutendsten Geschenken des Meeres. Ohne Seetang wäre mein Tonikum nutzlos.\n\nIch weiß, dass es keine einfache Sache ist, aber könntet Ihr Euch zum Hafen begeben und ein wenig davon für mich sammeln? Das Wasser ist derzeit sehr aufgewühlt, aber ich werde Euch meinen Segen geben.", sourceObjective = "Sammelt 8 Büschel Seetang vom Hafenseetang.", progress = "Das Meer kann uns nicht führen, wenn es solche Pein erleiden muss. Ich fühle mich, als wäre einer meiner eigenen Sinne geblendet.", completion = "Fantastisch! Das sollte allerdings genügen.", sourceObjectiveStatus = "unverified-source-field" }
quests[48353] = { id = 48353, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Geschehen an den Docks", description = "Ich weiß auch nicht, was los ist, {name}. Das Wasser schäumt und ich spüre seinen Schmerz, als wäre es mein eigener.\n\nIch bin ratlos, aber vielleicht haben die Händler in der Stadt ja etwas gesehen? Sie sind immer sehr neugierig und erzählen sich viel. Sie sind also immer eine gute Quelle für Informationen.", sourceObjective = "Sprecht mit Jan-Klaas Nilson, Inga Friedrich und Aaron Gutier in der Angelpunktwerft.", completion = "Im Namen des Meeres! Habt Ihr das gesehen?", sourceObjectiveStatus = "unverified-source-field" }
quests[48354] = { id = 48354, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kontaminierte Lieferungen", description = "Wenn eine Lieferung verseucht war, könnten auch viele andere betroffen sein.\n\nGanz in der Nähe werden Fische für den Versand nach ganz Kul Tiras verpackt. Wir müssen diese Lieferungen kontrollieren, bevor sich diese Seuche ausbreiten kann!", sourceObjective = "Untersucht 5 Fässer mit Fischen.", completion = "Mir fehlen die Worte... Wie konnte das nur direkt vor unseren Augen geschehen?", sourceObjectiveStatus = "unverified-source-field" }
quests[48355] = { id = 48355, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Evakuierung der Gefahrenbereiche", description = "Die Leute vom Angelpunkt erwarten von mir, dass ich in dieser unerklärlichen Situation die Ruhe bewahre und nicht in Panik verfalle.\n\nIch gebe zu, dass mir das Schwierigkeiten bereitet.\n\nSelbst jetzt verpacken die Arbeiter noch die verdorbenen Produkte für die Lieferungen. Sie sind in großer Gefahr und wir müssen etwas unternehmen.\n\nWir müssen sie in Sicherheit bringen!", sourceObjective = "Evakuiert 8 Fischpacker des Angelpunkts.", completion = "Wenn Unschuldige zu Schaden kommen könnten, müssen wir sie um jeden Preis beschützen.", sourceObjectiveStatus = "unverified-source-field" }
quests[48356] = { id = 48356, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Besitzergreifende Kopfbedeckung", description = "Zum Glück haben wir Albers gefunden. Er hat mir von der Situation an den Ladedocks berichtet.\n\nEs sieht nicht gut aus, {name}.\n\nDie Arbeiter wirken ganz normal und gehen umher und verrichten ihre Arbeit. Aber sie werden von Parasiten gesteuert. Es sind Gedankenräuber, die ihnen ihren freien Willen nehmen.\n\nSie sind es, die die Fracht verseuchen.\n\nIhr müsst so viele Gedankenräuber töten, wie Ihr könnt. Befreit die Gedanken der Befallenen!", sourceObjective = "Tötet 10 parasitäre Gedankenräuber, die besessene Dockarbeiter an den Ladedocks des Angelpunkts kontrollieren.", completion = "Das war zu keiner Zeit eine ganz normale Krankheit. Wir haben es hier mit verderbter Magie zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[48358] = { id = 48358, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Benötigte Vorräte: Empyrium", progress = "Seid Ihr hier, um Vorräte abzuliefern?", completion = "Danke für Eure Hilfe, {class}. Wir haben dieses Empyrium wirklich dringend gebraucht." }
quests[48359] = { id = 48359, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arbeitsauftrag: Infernalisches Leder", progress = "Seid Ihr hier, um Vorräte abzuliefern?", completion = "Danke für Eure Hilfe, Kürschner. Wir haben dieses infernalische Leder wirklich dringend gebraucht." }
quests[48360] = { id = 48360, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Benötigte Vorräte: Infernalisches Leder", progress = "Seid Ihr hier, um Vorräte abzuliefern?", completion = "Danke für Eure Hilfe, {class}. Wir haben dieses infernalische Leder wirklich dringend gebraucht." }
quests[48363] = { id = 48363, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arbeitsauftrag: Olivin", progress = "Seid Ihr hier, um Vorräte abzuliefern?", completion = "Danke für Eure Hilfe, Juwelenschleifer. Wir haben diesen Olivin wirklich dringend gebraucht." }
quests[48364] = { id = 48364, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arbeitsauftrag: Hesselit", progress = "Seid Ihr hier, um Vorräte abzuliefern?", completion = "Danke für Eure Hilfe, Juwelenschleifer. Wir haben diesen Hesselit wirklich dringend gebraucht." }
quests[48365] = { id = 48365, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der junge Lord Sturmsang", description = "Als die Stadt im Chaos versank, wurde ich von meinem Schützling getrennt.\n\nLord Sturmsang wird in seinem eigenen Haus gefangen gehalten. Ich hätte dort sein müssen, um ihn zu beschützen.\n\nWenn Ihr hineingeht, müsst Ihr erfolgreich sein, wo ich versagt habe. Bringt ihn unbeschadet zurück.", sourceObjective = "Tötet Bruder Klausen und rettet anschließend Lord Brannon Sturmsang an den Ladedocks des Angelpunkts.", completion = "<Albers räuspert sich.>\n\nEs ist schön, den jungen Lord in Sicherheit zu sehen.\n\n...Danke.", sourceObjectiveStatus = "unverified-source-field" }
quests[48366] = { id = 48366, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Sicherheit rudern", description = "Vielleicht... kann ich meinen Leuten doch noch helfen.\n\nIch habe die Gespräche zwischen dem Vorarbeiter und seinen Männern mitbekommen. Offenbar liegt die Quelle der Verderbnis im tiefen Gewässer, wo die Sturmtakler auf Monsterjagd gehen.\n\nBitte helft mir, die Sache zu untersuchen. Ich kann mich immer noch nützlich machen und bei dieser Operation helfen.", sourceObjective = "Reist mit dem Fluchtruderboot zum Sturmtaklerposten.", progress = "Ich kann nicht länger untätig bleiben.", completion = "Von hier aus können wir mit unserer Untersuchung beginnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[48367] = { id = 48367, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das sind keine Fischeier", description = "Die Verderbnis ist in das Meer gedrungen.\n\nUnsere Aufgabe ist es, die Monster in diesen Bereichen unter Kontrolle zu halten. Viele der Wesen wurden von einer furchterregenden Magie heimgesucht. Ich werde diese Herausforderung voller Stolz annehmen, aber wenn es zu viele werden, überrennen sie uns!\n\nDie Monstereier pulsieren mit einer dunklen Magie und liegen in der ganzen Brutstätte verteilt.\n\nZieht die festen Stiefel an.", sourceObjective = "Zerbrecht 30 verderbte Eier in der Krakenfluchbucht.", completion = "Es ist wohl am besten, nicht zu wissen, was daraus schlüpfen würde. Ich kann mir aber lebhaft vorstellen, welchen Kampf wir uns da erspart haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[48368] = { id = 48368, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die entweihte Tiefsee", description = "Das Meer...\n\nIch verstehe seine Schreie jetzt. Als hätte sich ein Schleier gelüftet und einen Blick auf das Chaos freigegeben.\n\nEin so großes Meeresgebiet kann nicht durch einfache Zauber verderbt werden. Die Kultisten müssen irgendwelche Gebilde errichtet haben, durch die sie ihre dunkle Magie kanalisieren...\n\nFindet und zerstört diese Gebilde, {name}. Nur so können wir das Gleichgewicht in den Gewässern wiederherstellen.", sourceObjective = "Zerstört die drei verderbenden Pylonen in den Unterwasserhöhlen in der Krakenfluchbucht.", progress = "Mein Verstand wird vom Wehklagen des Wassers fast zerrissen. Ich kann es kaum noch ertragen.", completion = "Die Schreie haben nachgelassen... ein bisschen jedenfalls.", sourceObjectiveStatus = "unverified-source-field" }
quests[48369] = { id = 48369, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neue Strategie", description = "Mein Sohn ist wohin gegangen? Er ist wieder einmal unseren Arbeitern in den Wald nachgejagt?\n\nDieser Junge ist zu weichherzig. Ganz gleich, was ich mache, er wird niemals stark genug sein, um das Familiengeschäft zu übernehmen.\n\nIch will, dass er auf der Stelle zurückkommt. Er hat Besseres zu tun, als sinnlos unseren Angestellten nachzulaufen!", sourceObjective = "Findet Benjamin Algerson in der Nähe der Farnwaldhöhe.", completion = "Vater lässt sich durch sein Streben nach Erfolg blenden. Wenn er unseren Angestellten nicht zuhören will, dann muss ich es eben tun!", sourceObjectiveStatus = "unverified-source-field" }
quests[48370] = { id = 48370, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Tod in den Tiefen", description = "Meine eigenen Leute sind dem wahnsinnigen Geflüster der Stimmen aus den Tiefen des Meeres verfallen.\n\nDie Kultisten wohnen in Höhlen im Meer, von denen aus sie mit ihren irren Ritualen die Hysterie in Tiragarde immer weiter schüren.\n\nWir müssen dem ein Ende setzen, {name}, bevor das Ganze noch weiter außer Kontrolle gerät.", sourceObjective = "Tötet 8 Anhänger von Tiefenwacht in der Krakenfluchbucht.", completion = "Vielleicht ist die Gefahr jetzt endlich gebannt.", sourceObjectiveStatus = "unverified-source-field" }
quests[48372] = { id = 48372, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unheimliche Anrufung", description = "Es ist meine Schuld, <mein Freund/meine Liebe>.\n\nDer Anführer der Kultisten ist niemand anderes als Vorsteher Tiefenwacht. Ein Mann, dem ich als Ratgeber und Geschäftspartner einmal vertraut habe.\n\nEs hat ihm wohl nicht gefallen, wie ich unser Geschäft geführt habe...\n\nEr opferte seine Menschlichkeit, um Macht zu erhalten, und benutzte seine Frustration, um das Dorf von innen heraus umzustürzen. Wer weiß, was er als Nächstes plant.\n\nIch kann nicht länger die Hände in den Schoß legen. Schaltet Tiefenwacht aus. Zeigt ihm, dass die Angelpunktbucht seinem Wahnsinn nicht verfallen wird.", sourceObjective = "Tötet Vorsteher Tiefenwacht in der Krakenfluchbucht.", completion = "Ist das wirklich das Ende?", sourceObjectiveStatus = "unverified-source-field" }
quests[48373] = { id = 48373, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arbeitsauftrag: Lichtgewirktes Tuch", progress = "Seid Ihr hier, um Vorräte abzuliefern?", completion = "Danke für Eure Hilfe, Schneider. Wir haben dieses lichtgewirkte Tuch wirklich dringend gebraucht." }
quests[48374] = { id = 48374, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Benötigte Vorräte: Lichtgewirktes Tuch", progress = "Seid Ihr hier, um Vorräte abzuliefern?", completion = "Danke für Eure Hilfe, {class}. Wir haben dieses lichtgewirkte Tuch wirklich dringend gebraucht." }
quests[48375] = { id = 48375, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Urobliterum", progress = "Oho, was habt Ihr denn da? Ursargerit? Klingt ja ganz schön edel!\n\nWenn wir etwas von dem Zeugs mit Obliterum mischen, bekommt es noch mehr Bums! Und wenn Ihr das dann auf Eure Rüstung auftragt - aber hoppla!\n\nUnd, woll'n wir's mal probieren?", completion = "<Nachdem Caelen das Sargerit mit dem Obliterum bei der Schmiede verbunden hat, geht von der Legierung eine recht beeindruckende Macht aus.>\n\nDa habt Ihr es, Söhnchen. Ob das Zeug wohl giftig ist? Bestimmt nicht, oder?" }
